INSERT INTO abilities VALUES (1, 'stench', 'generation-iii', 'This Pokémon''s damaging moves have a 10% chance to make the target flinch with each hit if they do not already cause flinching as a secondary effect.  This ability does not stack with a held item.  Overworld: The wild encounter rate is halved while this Pokémon is first in the party.', 'This Pokémon''s damaging moves have a 10% chance to make the target flinch with each hit if they do not already cause flinching as a secondary effect.  This ability does not stack with a held item.  Overworld: The wild encounter rate is halved while this Pokémon is first in the party.');
INSERT INTO abilities VALUES (2, 'drizzle', 'generation-iii', 'The weather changes to rain when this Pokémon enters battle and does not end unless replaced by another weather condition.  If multiple Pokémon with this ability, Drought, Sand Stream, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.', 'The weather changes to rain when this Pokémon enters battle and does not end unless replaced by another weather condition.  If multiple Pokémon with this ability, Drought, Sand Stream, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.');
INSERT INTO abilities VALUES (3, 'speed-boost', 'generation-iii', 'This Pokémon''s Speed rises one stage after each turn.', 'This Pokémon''s Speed rises one stage after each turn.');
INSERT INTO abilities VALUES (4, 'battle-armor', 'generation-iii', 'Moves cannot score critical hits against this Pokémon.  This ability functions identically to Shell Armor.', 'Moves cannot score critical hits against this Pokémon.  This ability functions identically to Shell Armor.');
INSERT INTO abilities VALUES (5, 'sturdy', 'generation-iii', 'When this Pokémon is at full HP, any hit that would knock it out will instead leave it with 1 HP.  Regardless of its current HP, it is also immune to the one-hit KO moves: Fissure, Guillotine, Horn Drill, and Sheer Cold.  If this Pokémon is holding a Focus Sash, this ability takes precedence and the item will not be consumed.', 'When this Pokémon is at full HP, any hit that would knock it out will instead leave it with 1 HP.  Regardless of its current HP, it is also immune to the one-hit KO moves: Fissure, Guillotine, Horn Drill, and Sheer Cold.  If this Pokémon is holding a Focus Sash, this ability takes precedence and the item will not be consumed.');
INSERT INTO abilities VALUES (6, 'damp', 'generation-iii', 'While this Pokémon is in battle, Self-Destruct and Explosion will fail and Aftermath will not take effect.', 'While this Pokémon is in battle, Self-Destruct and Explosion will fail and Aftermath will not take effect.');
INSERT INTO abilities VALUES (7, 'limber', 'generation-iii', 'This Pokémon cannot be paralyzed.  If a Pokémon is paralyzed and acquires this ability, its paralysis is healed; this includes when regaining a lost ability upon leaving battle.', 'This Pokémon cannot be paralyzed.  If a Pokémon is paralyzed and acquires this ability, its paralysis is healed; this includes when regaining a lost ability upon leaving battle.');
INSERT INTO abilities VALUES (8, 'sand-veil', 'generation-iii', 'During a sandstorm, this Pokémon has 1.25× its evasion, and it does not take sandstorm damage regardless of type.  The evasion bonus does not count as a stat modifier.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in a sandstorm.', 'During a sandstorm, this Pokémon has 1.25× its evasion, and it does not take sandstorm damage regardless of type.  The evasion bonus does not count as a stat modifier.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in a sandstorm.');
INSERT INTO abilities VALUES (9, 'static', 'generation-iii', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being paralyzed.  Pokémon that are immune to Electric-type moves can still be paralyzed by this ability.  Overworld: If the lead Pokémon has this ability, there is a 50% chance that encounters will be with an Electric Pokémon, if applicable.', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being paralyzed.  Pokémon that are immune to Electric-type moves can still be paralyzed by this ability.  Overworld: If the lead Pokémon has this ability, there is a 50% chance that encounters will be with an Electric Pokémon, if applicable.');
INSERT INTO abilities VALUES (10, 'volt-absorb', 'generation-iii', 'Whenever an Electric-type move hits this Pokémon, it heals for 1/4 of its maximum HP, negating any other effect on it.  This ability will not take effect if this Pokémon is Ground-type and thus immune to Electric moves.  Electric moves will ignore this Pokémon''s Substitute.  This effect includes non-damaging moves, i.e. Thunder Wave.', 'Whenever an Electric-type move hits this Pokémon, it heals for 1/4 of its maximum HP, negating any other effect on it.  This ability will not take effect if this Pokémon is Ground-type and thus immune to Electric moves.  Electric moves will ignore this Pokémon''s Substitute.  This effect includes non-damaging moves, i.e. Thunder Wave.');
INSERT INTO abilities VALUES (11, 'water-absorb', 'generation-iii', 'Whenever a Water-type move hits this Pokémon, it heals for 1/4 of its maximum HP, negating any other effect on it.  Water moves will ignore this Pokémon''s Substitute.', 'Whenever a Water-type move hits this Pokémon, it heals for 1/4 of its maximum HP, negating any other effect on it.  Water moves will ignore this Pokémon''s Substitute.');
INSERT INTO abilities VALUES (12, 'oblivious', 'generation-iii', 'This Pokémon cannot be infatuated and is immune to Captivate.  If a Pokémon is infatuated and acquires this ability, its infatuation is cleared.', 'This Pokémon cannot be infatuated and is immune to Captivate.  If a Pokémon is infatuated and acquires this ability, its infatuation is cleared.');
INSERT INTO abilities VALUES (13, 'cloud-nine', 'generation-iii', 'While this Pokémon is in battle, weather can still be in play, but will not have any of its effects.  This ability functions identically to Air Lock.', 'While this Pokémon is in battle, weather can still be in play, but will not have any of its effects.  This ability functions identically to Air Lock.');
INSERT INTO abilities VALUES (14, 'compound-eyes', 'generation-iii', 'This Pokémon''s moves have 1.3× their accuracy.  This ability has no effect on the one-hit KO moves (Fissure, Guillotine, Horn Drill, and Sheer Cold).  Overworld: If the first Pokémon in the party has this ability, the chance of a wild Pokémon holding a particular item is raised from 50%, 5%, or 1% to 60%, 20%, or 5%, respectively.', 'This Pokémon''s moves have 1.3× their accuracy.  This ability has no effect on the one-hit KO moves (Fissure, Guillotine, Horn Drill, and Sheer Cold).  Overworld: If the first Pokémon in the party has this ability, the chance of a wild Pokémon holding a particular item is raised from 50%, 5%, or 1% to 60%, 20%, or 5%, respectively.');
INSERT INTO abilities VALUES (15, 'insomnia', 'generation-iii', 'This Pokémon cannot be asleep.  This causes Rest to fail altogether.  If a Pokémon is asleep and acquires this ability, it will immediately wake up; this includes when regaining a lost ability upon leaving battle.  This ability functions identically to Vital Spirit in battle.', 'This Pokémon cannot be asleep.  This causes Rest to fail altogether.  If a Pokémon is asleep and acquires this ability, it will immediately wake up; this includes when regaining a lost ability upon leaving battle.  This ability functions identically to Vital Spirit in battle.');
INSERT INTO abilities VALUES (16, 'color-change', 'generation-iii', 'Whenever this Pokémon takes damage from a move, the Pokémon''s type changes to match the move.  If the Pokémon has two types, both are overridden.  The Pokémon must directly take damage; for example, moves blocked by a Substitute will not trigger this ability, nor will moves that deal damage indirectly, such as Spikes.  This ability takes effect on only the last hit of a multiple-hit attack.  In Pokémon Colosseum and XD: Gale of Darkness, this ability does not take effect on Shadow-type moves.', 'Whenever this Pokémon takes damage from a move, the Pokémon''s type changes to match the move.  If the Pokémon has two types, both are overridden.  The Pokémon must directly take damage; for example, moves blocked by a Substitute will not trigger this ability, nor will moves that deal damage indirectly, such as Spikes.  This ability takes effect on only the last hit of a multiple-hit attack.  In Pokémon Colosseum and XD: Gale of Darkness, this ability does not take effect on Shadow-type moves.');
INSERT INTO abilities VALUES (17, 'immunity', 'generation-iii', 'This Pokémon cannot be poisoned.  This includes bad poison.  If a Pokémon is poisoned and acquires this ability, its poison is healed; this includes when regaining a lost ability upon leaving battle.', 'This Pokémon cannot be poisoned.  This includes bad poison.  If a Pokémon is poisoned and acquires this ability, its poison is healed; this includes when regaining a lost ability upon leaving battle.');
INSERT INTO abilities VALUES (18, 'flash-fire', 'generation-iii', 'This Pokémon is immune to Fire-type moves.  Once this Pokémon has been hit by a Fire move, its own Fire moves will inflict 1.5× as much damage until it leaves battle.  This ability has no effect while the Pokémon is frozen.  The Fire damage bonus is retained even if the Pokémon is frozen and thawed or the ability is lost or disabled.  Fire moves will ignore this Pokémon''s Substitute.  This ability takes effect even on non-damaging moves, i.e. Will-O-Wisp.', 'This Pokémon is immune to Fire-type moves.  Once this Pokémon has been hit by a Fire move, its own Fire moves will inflict 1.5× as much damage until it leaves battle.  This ability has no effect while the Pokémon is frozen.  The Fire damage bonus is retained even if the Pokémon is frozen and thawed or the ability is lost or disabled.  Fire moves will ignore this Pokémon''s Substitute.  This ability takes effect even on non-damaging moves, i.e. Will-O-Wisp.');
INSERT INTO abilities VALUES (19, 'shield-dust', 'generation-iii', 'This Pokémon is immune to the extra effects of moves used against it.  An extra effect is a move''s chance, listed as an "effect chance", to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move''s main effect.  For example, Thunder Shock''s paralysis is an extra effect, but Thunder Wave''s is not, nor are Knock Off''s item removal and Air Cutter''s increased critical hit rate.', 'This Pokémon is immune to the extra effects of moves used against it.  An extra effect is a move''s chance, listed as an "effect chance", to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move''s main effect.  For example, Thunder Shock''s paralysis is an extra effect, but Thunder Wave''s is not, nor are Knock Off''s item removal and Air Cutter''s increased critical hit rate.');
INSERT INTO abilities VALUES (20, 'own-tempo', 'generation-iii', 'This Pokémon cannot be confused.  If a Pokémon is confused and acquires this ability, its confusion will immediately be healed.', 'This Pokémon cannot be confused.  If a Pokémon is confused and acquires this ability, its confusion will immediately be healed.');
INSERT INTO abilities VALUES (21, 'suction-cups', 'generation-iii', 'This Pokémon cannot be forced out of battle by moves such as Whirlwind.  Dragon Tail and Circle Throw still inflict damage against this Pokémon.  Overworld: If the lead Pokémon has this ability, the success rate while fishing is increased.', 'This Pokémon cannot be forced out of battle by moves such as Whirlwind.  Dragon Tail and Circle Throw still inflict damage against this Pokémon.  Overworld: If the lead Pokémon has this ability, the success rate while fishing is increased.');
INSERT INTO abilities VALUES (22, 'intimidate', 'generation-iii', 'When this Pokémon enters battle, the opponent''s Attack is lowered by one stage.  In a double battle, both opponents are affected.  This ability also takes effect when acquired during a battle, but will not take effect again if lost and reobtained without leaving battle.  This ability has no effect on an opponent that has a Substitute.  Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped.', 'When this Pokémon enters battle, the opponent''s Attack is lowered by one stage.  In a double battle, both opponents are affected.  This ability also takes effect when acquired during a battle, but will not take effect again if lost and reobtained without leaving battle.  This ability has no effect on an opponent that has a Substitute.  Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped.');
INSERT INTO abilities VALUES (23, 'shadow-tag', 'generation-iii', 'While this Pokémon is in battle, opposing Pokémon cannot flee or switch out.  Other Pokémon with this ability are unaffected.  Pokémon with Run Away can still flee.  Pokémon can still switch out with the use of a move or item.', 'While this Pokémon is in battle, opposing Pokémon cannot flee or switch out.  Other Pokémon with this ability are unaffected.  Pokémon with Run Away can still flee.  Pokémon can still switch out with the use of a move or item.');
INSERT INTO abilities VALUES (24, 'rough-skin', 'generation-iii', 'Whenever a move makes contact with this Pokémon, the move''s user takes 1/8 of its maximum HP in damage.  This ability functions identically to Iron Barbs.', 'Whenever a move makes contact with this Pokémon, the move''s user takes 1/8 of its maximum HP in damage.  This ability functions identically to Iron Barbs.');
INSERT INTO abilities VALUES (25, 'wonder-guard', 'generation-iii', 'This Pokémon is immune to damaging moves that are not super effective against it.  Moves that inflict fixed damage, such as Night Shade or Seismic Toss, are considered super effective if their types are.  Damage not directly dealt by moves, such as damage from weather, a status ailment, or Spikes, is not prevented.  This ability cannot be copied with Role Play or traded away with Skill Swap, but it can be copied with Trace, disabled with Gastro Acid, or changed with Worry Seed.  This Pokémon can still use Role Play itself to lose this ability, but not Skill Swap.  If this Pokémon has a Substitute, this ability will block moves as usual and any moves not blocked will react to the Substitute as usual.', 'This Pokémon is immune to damaging moves that are not super effective against it.  Moves that inflict fixed damage, such as Night Shade or Seismic Toss, are considered super effective if their types are.  Damage not directly dealt by moves, such as damage from weather, a status ailment, or Spikes, is not prevented.  This ability cannot be copied with Role Play or traded away with Skill Swap, but it can be copied with Trace, disabled with Gastro Acid, or changed with Worry Seed.  This Pokémon can still use Role Play itself to lose this ability, but not Skill Swap.  If this Pokémon has a Substitute, this ability will block moves as usual and any moves not blocked will react to the Substitute as usual.');
INSERT INTO abilities VALUES (26, 'levitate', 'generation-iii', 'This Pokémon is immune to Ground-type moves, Spikes, Toxic Spikes, and Arena Trap.  This ability is disabled during Gravity or Ingrain, or while holding an Iron Ball.  This ability is not disabled during Roost.', 'This Pokémon is immune to Ground-type moves, Spikes, Toxic Spikes, and Arena Trap.  This ability is disabled during Gravity or Ingrain, or while holding an Iron Ball.  This ability is not disabled during Roost.');
INSERT INTO abilities VALUES (27, 'effect-spore', 'generation-iii', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being paralyzed, poisoned, or put to sleep, chosen at random.  Nothing is done to compensate if the move''s user is immune to one of these ailments; there is simply a lower chance that the move''s user will be affected.', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being paralyzed, poisoned, or put to sleep, chosen at random.  Nothing is done to compensate if the move''s user is immune to one of these ailments; there is simply a lower chance that the move''s user will be affected.');
INSERT INTO abilities VALUES (28, 'synchronize', 'generation-iii', 'Whenever this Pokémon is burned, paralyzed, or poisoned, the Pokémon who gave this Pokémon that ailment is also given the ailment.  This ability passes back bad poison when this Pokémon is badly poisoned.  This ability cannot pass on a status ailment that the Pokémon did not directly receive from another Pokémon, such as the poison from Toxic Spikes or the burn from a Flame Orb.  Overworld: If the lead Pokémon has this ability, wild Pokémon have a 50% chance of having the lead Pokémon''s nature, and a 50% chance of being given a random nature as usual, including the lead Pokémon''s nature.  This does not work on Pokémon received outside of battle or roaming legendaries.', 'Whenever this Pokémon is burned, paralyzed, or poisoned, the Pokémon who gave this Pokémon that ailment is also given the ailment.  This ability passes back bad poison when this Pokémon is badly poisoned.  This ability cannot pass on a status ailment that the Pokémon did not directly receive from another Pokémon, such as the poison from Toxic Spikes or the burn from a Flame Orb.  Overworld: If the lead Pokémon has this ability, wild Pokémon have a 50% chance of having the lead Pokémon''s nature, and a 50% chance of being given a random nature as usual, including the lead Pokémon''s nature.  This does not work on Pokémon received outside of battle or roaming legendaries.');
INSERT INTO abilities VALUES (29, 'clear-body', 'generation-iii', 'This Pokémon cannot have its stats lowered by other Pokémon.  This ability does not prevent any stat losses other than stat modifiers, such as the Speed cut from paralysis.  This Pokémon can still be passed negative stat modifiers through Guard Swap, Heart Swap, or Power Swap.  This ability functions identically to White Smoke in battle.', 'This Pokémon cannot have its stats lowered by other Pokémon.  This ability does not prevent any stat losses other than stat modifiers, such as the Speed cut from paralysis.  This Pokémon can still be passed negative stat modifiers through Guard Swap, Heart Swap, or Power Swap.  This ability functions identically to White Smoke in battle.');
INSERT INTO abilities VALUES (30, 'natural-cure', 'generation-iii', 'This Pokémon is cured of any major status ailment when it is switched out for another Pokémon.  If this ability is acquired during battle, the Pokémon is cured upon leaving battle before losing the temporary ability.', 'This Pokémon is cured of any major status ailment when it is switched out for another Pokémon.  If this ability is acquired during battle, the Pokémon is cured upon leaving battle before losing the temporary ability.');
INSERT INTO abilities VALUES (31, 'lightning-rod', 'generation-iii', 'All other Pokémon''s single-target Electric-type moves are redirected to this Pokémon if it is an eligible target.  Other Pokémon''s Electric moves raise this Pokémon''s Special Attack one stage, negating any other effect on it, and cannot miss it.  If the move''s intended target also has this ability, the move is not redirected.  When multiple Pokémon with this ability are possible targets for redirection, the move is redirected to the one with the highest Speed stat, or, in the case of a tie, to a random tied Pokémon.  Follow Me takes precedence over this ability.  If the Pokémon is a Ground-type and thus immune to Electric moves, its immunity prevents the Special Attack boost.', 'All other Pokémon''s single-target Electric-type moves are redirected to this Pokémon if it is an eligible target.  Other Pokémon''s Electric moves raise this Pokémon''s Special Attack one stage, negating any other effect on it, and cannot miss it.  If the move''s intended target also has this ability, the move is not redirected.  When multiple Pokémon with this ability are possible targets for redirection, the move is redirected to the one with the highest Speed stat, or, in the case of a tie, to a random tied Pokémon.  Follow Me takes precedence over this ability.  If the Pokémon is a Ground-type and thus immune to Electric moves, its immunity prevents the Special Attack boost.');
INSERT INTO abilities VALUES (32, 'serene-grace', 'generation-iii', 'This Pokémon''s moves have twice their usual effect chance.  An effect chance is a move''s chance to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move''s main effect.  For example, Flamethrower''s chance of burning the target is doubled, but Protect''s chance of success and Air Cutter''s increased critical hit rate are unaffected.  Secret Power is unaffected.', 'This Pokémon''s moves have twice their usual effect chance.  An effect chance is a move''s chance to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move''s main effect.  For example, Flamethrower''s chance of burning the target is doubled, but Protect''s chance of success and Air Cutter''s increased critical hit rate are unaffected.  Secret Power is unaffected.');
INSERT INTO abilities VALUES (33, 'swift-swim', 'generation-iii', 'This Pokémon''s Speed is doubled during rain.  This bonus does not count as a stat modifier.', 'This Pokémon''s Speed is doubled during rain.  This bonus does not count as a stat modifier.');
INSERT INTO abilities VALUES (34, 'chlorophyll', 'generation-iii', 'This Pokémon''s Speed is doubled during strong sunlight.  This bonus does not count as a stat modifier.', 'This Pokémon''s Speed is doubled during strong sunlight.  This bonus does not count as a stat modifier.');
INSERT INTO abilities VALUES (35, 'illuminate', 'generation-iii', 'Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.  This ability has no effect in battle.', 'Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.  This ability has no effect in battle.');
INSERT INTO abilities VALUES (36, 'trace', 'generation-iii', 'When this Pokémon enters battle, it copies a random opponent''s ability.  This ability cannot copy Flower Gift, Forecast, Illusion, Imposter, Multitype, Trace, Wonder Guard, or Zen Mode.', 'When this Pokémon enters battle, it copies a random opponent''s ability.  This ability cannot copy Flower Gift, Forecast, Illusion, Imposter, Multitype, Trace, Wonder Guard, or Zen Mode.');
INSERT INTO abilities VALUES (37, 'huge-power', 'generation-iii', 'This Pokémon''s Attack is doubled while in battle.  This bonus does not count as a stat modifier.  This ability functions identically to Pure Power.', 'This Pokémon''s Attack is doubled while in battle.  This bonus does not count as a stat modifier.  This ability functions identically to Pure Power.');
INSERT INTO abilities VALUES (38, 'poison-point', 'generation-iii', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being poisoned.', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being poisoned.');
INSERT INTO abilities VALUES (39, 'inner-focus', 'generation-iii', 'This Pokémon cannot flinch.', 'This Pokémon cannot flinch.');
INSERT INTO abilities VALUES (40, 'magma-armor', 'generation-iii', 'This Pokémon cannot be frozen.  If a Pokémon is frozen and acquires this ability, it will immediately thaw out; this includes when regaining a lost ability upon leaving battle.  Overworld: If any Pokémon in the party has this ability, each egg in the party has its hatch counter decreased by 2 (rather than 1) each step cycle, making eggs hatch roughly twice as quickly.  This effect does not stack if multiple Pokémon have this ability or Flame Body.', 'This Pokémon cannot be frozen.  If a Pokémon is frozen and acquires this ability, it will immediately thaw out; this includes when regaining a lost ability upon leaving battle.  Overworld: If any Pokémon in the party has this ability, each egg in the party has its hatch counter decreased by 2 (rather than 1) each step cycle, making eggs hatch roughly twice as quickly.  This effect does not stack if multiple Pokémon have this ability or Flame Body.');
INSERT INTO abilities VALUES (41, 'water-veil', 'generation-iii', 'This Pokémon cannot be burned.  If a Pokémon is burned and acquires this ability, its burn is healed; this includes when regaining a lost ability upon leaving battle.', 'This Pokémon cannot be burned.  If a Pokémon is burned and acquires this ability, its burn is healed; this includes when regaining a lost ability upon leaving battle.');
INSERT INTO abilities VALUES (42, 'magnet-pull', 'generation-iii', 'While this Pokémon is in battle, opposing Steel-type Pokémon cannot flee or switch out.  Pokémon with Run Away can still flee.  Pokémon can still switch out with the use of a move or item.  Overworld: If the lead Pokémon has this ability, Steel-type Pokémon have a higher encounter rate.', 'While this Pokémon is in battle, opposing Steel-type Pokémon cannot flee or switch out.  Pokémon with Run Away can still flee.  Pokémon can still switch out with the use of a move or item.  Overworld: If the lead Pokémon has this ability, Steel-type Pokémon have a higher encounter rate.');
INSERT INTO abilities VALUES (43, 'soundproof', 'generation-iii', 'This Pokémon is immune to moves flagged as being sound-based.  Heal Bell is unaffected.  Uproar still prevents this Pokémon from sleeping.  This Pokémon can still receive a Perish Song counter through Baton Pass, and will retain a Perish Song counter if it acquires this ability after Perish Song is used.  Howl, Roar of Time, Sonic Boom, and Yawn are not flagged as sound-based.', 'This Pokémon is immune to moves flagged as being sound-based.  Heal Bell is unaffected.  Uproar still prevents this Pokémon from sleeping.  This Pokémon can still receive a Perish Song counter through Baton Pass, and will retain a Perish Song counter if it acquires this ability after Perish Song is used.  Howl, Roar of Time, Sonic Boom, and Yawn are not flagged as sound-based.');
INSERT INTO abilities VALUES (44, 'rain-dish', 'generation-iii', 'This Pokémon heals for 1/16 of its maximum HP after each turn during rain.', 'This Pokémon heals for 1/16 of its maximum HP after each turn during rain.');
INSERT INTO abilities VALUES (45, 'sand-stream', 'generation-iii', 'The weather changes to a sandstorm when this Pokémon enters battle and does not end unless cancelled by another weather condition.  If multiple Pokémon with this ability, Drizzle, Drought, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in a sandstorm.', 'The weather changes to a sandstorm when this Pokémon enters battle and does not end unless cancelled by another weather condition.  If multiple Pokémon with this ability, Drizzle, Drought, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in a sandstorm.');
INSERT INTO abilities VALUES (46, 'pressure', 'generation-iii', 'Moves targetting this Pokémon use one extra PP.  This ability stacks if multiple targets have it.  This ability still affects moves that fail or miss.  This ability does not affect ally moves that target either the entire field or just its side, nor this Pokémon''s self-targetted moves; it does, however, affect single-targetted ally moves aimed at this Pokémon, ally moves that target all other Pokémon, and opponents'' moves that target the entire field.  If this ability raises a move''s PP cost above its remaining PP, it will use all remaining PP.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.', 'Moves targetting this Pokémon use one extra PP.  This ability stacks if multiple targets have it.  This ability still affects moves that fail or miss.  This ability does not affect ally moves that target either the entire field or just its side, nor this Pokémon''s self-targetted moves; it does, however, affect single-targetted ally moves aimed at this Pokémon, ally moves that target all other Pokémon, and opponents'' moves that target the entire field.  If this ability raises a move''s PP cost above its remaining PP, it will use all remaining PP.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.');
INSERT INTO abilities VALUES (47, 'thick-fat', 'generation-iii', 'This Pokémon takes half as much damage from Fire- and Ice-type moves.', 'This Pokémon takes half as much damage from Fire- and Ice-type moves.');
INSERT INTO abilities VALUES (48, 'early-bird', 'generation-iii', 'This Pokémon''s remaining sleep turn count falls by 2 rather than 1.  If this Pokémon''s sleep counter is at 1, it will fall to 0 and then the Pokémon will wake up.', 'This Pokémon''s remaining sleep turn count falls by 2 rather than 1.  If this Pokémon''s sleep counter is at 1, it will fall to 0 and then the Pokémon will wake up.');
INSERT INTO abilities VALUES (49, 'flame-body', 'generation-iii', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being burned.  Overworld: If any Pokémon in the party has this ability, each egg in the party has its hatch counter decreased by 2 (rather than 1) each step cycle, making eggs hatch roughly twice as quickly.  This effect does not stack if multiple Pokémon have this ability or Magma Armor.', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being burned.  Overworld: If any Pokémon in the party has this ability, each egg in the party has its hatch counter decreased by 2 (rather than 1) each step cycle, making eggs hatch roughly twice as quickly.  This effect does not stack if multiple Pokémon have this ability or Magma Armor.');
INSERT INTO abilities VALUES (50, 'run-away', 'generation-iii', 'This Pokémon is always successful fleeing from wild battles, even if trapped by a move or ability.', 'This Pokémon is always successful fleeing from wild battles, even if trapped by a move or ability.');
INSERT INTO abilities VALUES (51, 'keen-eye', 'generation-iii', 'This Pokémon cannot have its accuracy lowered.  This ability does not prevent any accuracy losses other than stat modifiers, such as the accuracy cut from fog; nor does it prevent other Pokémon''s evasion from making this Pokémon''s moves less accurate.  This Pokémon can still be passed negative accuracy modifiers through Heart Swap.  Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped.', 'This Pokémon cannot have its accuracy lowered.  This ability does not prevent any accuracy losses other than stat modifiers, such as the accuracy cut from fog; nor does it prevent other Pokémon''s evasion from making this Pokémon''s moves less accurate.  This Pokémon can still be passed negative accuracy modifiers through Heart Swap.  Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped.');
INSERT INTO abilities VALUES (52, 'hyper-cutter', 'generation-iii', 'This Pokémon''s Attack cannot be lowered by other Pokémon.  This ability does not prevent any Attack losses other than stat modifiers, such as the Attack cut from a burn.  This Pokémon can still be passed negative Attack modifiers through Heart Swap or Power Swap.', 'This Pokémon''s Attack cannot be lowered by other Pokémon.  This ability does not prevent any Attack losses other than stat modifiers, such as the Attack cut from a burn.  This Pokémon can still be passed negative Attack modifiers through Heart Swap or Power Swap.');
INSERT INTO abilities VALUES (53, 'pickup', 'generation-iii', 'At the end of each turn, if another Pokémon consumed or Flung a held item that turn, this Pokémon picks up the item if it is not already holding one.  After each battle, this Pokémon has a 10% chance of picking up an item if it is not already holding one.  The Air Balloon and Eject Button cannot be picked up.  The items that may be found vary by game, and, since Pokémon Emerald, by the Pokémon''s level.  This ability is checked after the battle ends, at which point any temporary ability changes have worn off.', 'At the end of each turn, if another Pokémon consumed or Flung a held item that turn, this Pokémon picks up the item if it is not already holding one.  After each battle, this Pokémon has a 10% chance of picking up an item if it is not already holding one.  The Air Balloon and Eject Button cannot be picked up.  The items that may be found vary by game, and, since Pokémon Emerald, by the Pokémon''s level.  This ability is checked after the battle ends, at which point any temporary ability changes have worn off.');
INSERT INTO abilities VALUES (54, 'truant', 'generation-iii', 'Every second turn on which this Pokémon should attempt to use a move, it will instead do nothing ("loaf around").  Loafing around interrupts moves that take multiple turns the same way paralysis, flinching, etc do.  Most such moves, for example Bide or Rollout, are simply cut off upon loafing around.  Attacks with a recharge turn, such as Hyper Beam, do not have to recharge; attacks with a preparation turn, such as Fly, do not end up being used.  Moves that are forced over multiple turns and keep going through failure, such as Outrage, Uproar, or any move forced by Encore, keep going as usual.  If this Pokémon is confused, its confusion is not checked when loafing around; the Pokémon cannot hurt itself, and its confusion does not end or come closer to ending.  If this Pokémon attempts to move but fails, e.g. because of paralysis or Gravity, it still counts as having moved and will loaf around the next turn.  If it does not attempt to move, e.g. because it is asleep or frozen, whatever it would have done will be postponed until its next attempt; that is, it will either loaf around or move as usual, depending on what it last did.  This ability cannot be changed with Worry Seed, but it can be disabled with Gastro Acid, changed with Role Play, or traded away with Skill Swap.', 'Every second turn on which this Pokémon should attempt to use a move, it will instead do nothing ("loaf around").  Loafing around interrupts moves that take multiple turns the same way paralysis, flinching, etc do.  Most such moves, for example Bide or Rollout, are simply cut off upon loafing around.  Attacks with a recharge turn, such as Hyper Beam, do not have to recharge; attacks with a preparation turn, such as Fly, do not end up being used.  Moves that are forced over multiple turns and keep going through failure, such as Outrage, Uproar, or any move forced by Encore, keep going as usual.  If this Pokémon is confused, its confusion is not checked when loafing around; the Pokémon cannot hurt itself, and its confusion does not end or come closer to ending.  If this Pokémon attempts to move but fails, e.g. because of paralysis or Gravity, it still counts as having moved and will loaf around the next turn.  If it does not attempt to move, e.g. because it is asleep or frozen, whatever it would have done will be postponed until its next attempt; that is, it will either loaf around or move as usual, depending on what it last did.  This ability cannot be changed with Worry Seed, but it can be disabled with Gastro Acid, changed with Role Play, or traded away with Skill Swap.');
INSERT INTO abilities VALUES (55, 'hustle', 'generation-iii', 'This Pokémon''s physical moves do 1.5× as much regular damage, but have 0.8× their usual accuracy.  Special moves are unaffected.  Moves that do set damage, such as Seismic Toss, have their accuracy affected, but not their damage.  Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.', 'This Pokémon''s physical moves do 1.5× as much regular damage, but have 0.8× their usual accuracy.  Special moves are unaffected.  Moves that do set damage, such as Seismic Toss, have their accuracy affected, but not their damage.  Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.');
INSERT INTO abilities VALUES (56, 'cute-charm', 'generation-iii', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being infatuated.  Overworld: If the first Pokémon in the party has this ability, any wild Pokémon whose species can be either gender has a 2/3 chance of being set to the opposite gender, and a 1/3 chance of having a random gender as usual.', 'Whenever a move makes contact with this Pokémon, the move''s user has a 30% chance of being infatuated.  Overworld: If the first Pokémon in the party has this ability, any wild Pokémon whose species can be either gender has a 2/3 chance of being set to the opposite gender, and a 1/3 chance of having a random gender as usual.');
INSERT INTO abilities VALUES (57, 'plus', 'generation-iii', 'This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus or Minus.  This bonus does not count as a stat modifier.  If either ability is disabled by Gastro Acid, both lose their effect.', 'This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus or Minus.  This bonus does not count as a stat modifier.  If either ability is disabled by Gastro Acid, both lose their effect.');
INSERT INTO abilities VALUES (58, 'minus', 'generation-iii', 'This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus or Minus.  This bonus does not count as a stat modifier.  If either ability is disabled by Gastro Acid, both lose their effect.', 'This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus or Minus.  This bonus does not count as a stat modifier.  If either ability is disabled by Gastro Acid, both lose their effect.');
INSERT INTO abilities VALUES (59, 'forecast', 'generation-iii', 'During rain, strong sunlight, or hail, this Pokémon''s type changes to Water, Fire, or Ice, respectively, and its form changes to match.  This ability has no effect for any Pokémon other than Castform.  If the weather ends or becomes anything that does not trigger this ability, or a Pokémon with Air Lock or Cloud Nine enters battle, this Pokémon''s type and form revert to their default.  If this ability is lost or disabled, this Pokémon cannot change its current type and form until it regains its ability.', 'During rain, strong sunlight, or hail, this Pokémon''s type changes to Water, Fire, or Ice, respectively, and its form changes to match.  This ability has no effect for any Pokémon other than Castform.  If the weather ends or becomes anything that does not trigger this ability, or a Pokémon with Air Lock or Cloud Nine enters battle, this Pokémon''s type and form revert to their default.  If this ability is lost or disabled, this Pokémon cannot change its current type and form until it regains its ability.');
INSERT INTO abilities VALUES (60, 'sticky-hold', 'generation-iii', 'This Pokémon''s hold item cannot be removed by other Pokémon.  Damaging moves that would remove this Pokémon''s item can still inflict damage against this Pokémon, e.g. Knock Off or Pluck.  This Pokémon can still use moves that involve the loss of its own item, e.g. Fling or Trick.  Overworld: If the lead Pokémon has this ability, the encounter rate while fishing is increased.', 'This Pokémon''s hold item cannot be removed by other Pokémon.  Damaging moves that would remove this Pokémon''s item can still inflict damage against this Pokémon, e.g. Knock Off or Pluck.  This Pokémon can still use moves that involve the loss of its own item, e.g. Fling or Trick.  Overworld: If the lead Pokémon has this ability, the encounter rate while fishing is increased.');
INSERT INTO abilities VALUES (61, 'shed-skin', 'generation-iii', 'After each turn, this Pokémon has a 33% of being cured of any major status ailment.', 'After each turn, this Pokémon has a 33% of being cured of any major status ailment.');
INSERT INTO abilities VALUES (62, 'guts', 'generation-iii', 'Whenever this Pokémon is asleep, burned, paralyzed, or poisoned, it has 1.5× its Attack.  This Pokémon is not affected by the usual Attack cut from a burn.  This bonus does not count as a stat modifier.', 'Whenever this Pokémon is asleep, burned, paralyzed, or poisoned, it has 1.5× its Attack.  This Pokémon is not affected by the usual Attack cut from a burn.  This bonus does not count as a stat modifier.');
INSERT INTO abilities VALUES (63, 'marvel-scale', 'generation-iii', 'Whenever this Pokémon has a major status ailment, it has 1.5× its Defense.  This bonus does not count as a stat modifier.', 'Whenever this Pokémon has a major status ailment, it has 1.5× its Defense.  This bonus does not count as a stat modifier.');
INSERT INTO abilities VALUES (64, 'liquid-ooze', 'generation-iii', 'Whenever a Pokémon would heal after hitting this Pokémon with a leeching move like Absorb, it instead loses as many HP as it would usually gain.  Dream Eater is unaffected.', 'Whenever a Pokémon would heal after hitting this Pokémon with a leeching move like Absorb, it instead loses as many HP as it would usually gain.  Dream Eater is unaffected.');
INSERT INTO abilities VALUES (65, 'overgrow', 'generation-iii', 'When this Pokémon has 1/3 or less of its HP remaining, its Grass-type moves inflict 1.5× as much regular damage.', 'When this Pokémon has 1/3 or less of its HP remaining, its Grass-type moves inflict 1.5× as much regular damage.');
INSERT INTO abilities VALUES (66, 'blaze', 'generation-iii', 'When this Pokémon has 1/3 or less of its HP remaining, its Fire-type moves inflict 1.5× as much regular damage.', 'When this Pokémon has 1/3 or less of its HP remaining, its Fire-type moves inflict 1.5× as much regular damage.');
INSERT INTO abilities VALUES (67, 'torrent', 'generation-iii', 'When this Pokémon has 1/3 or less of its HP remaining, its Water-type moves inflict 1.5× as much regular damage.', 'When this Pokémon has 1/3 or less of its HP remaining, its Water-type moves inflict 1.5× as much regular damage.');
INSERT INTO abilities VALUES (68, 'swarm', 'generation-iii', 'When this Pokémon has 1/3 or less of its HP remaining, its Bug-type moves inflict 1.5× as much regular damage.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is increased.', 'When this Pokémon has 1/3 or less of its HP remaining, its Bug-type moves inflict 1.5× as much regular damage.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is increased.');
INSERT INTO abilities VALUES (69, 'rock-head', 'generation-iii', 'This Pokémon does not receive recoil damage from its recoil moves.  Struggle''s recoil is unaffected.  This ability does not prevent crash damage from missing with Jump Kick or High Jump Kick.', 'This Pokémon does not receive recoil damage from its recoil moves.  Struggle''s recoil is unaffected.  This ability does not prevent crash damage from missing with Jump Kick or High Jump Kick.');
INSERT INTO abilities VALUES (70, 'drought', 'generation-iii', 'The weather changes to strong sunlight when this Pokémon enters battle and does not end unless cancelled by another weather condition.  If multiple Pokémon with this ability, Drizzle, Sand Stream, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.', 'The weather changes to strong sunlight when this Pokémon enters battle and does not end unless cancelled by another weather condition.  If multiple Pokémon with this ability, Drizzle, Sand Stream, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.');
INSERT INTO abilities VALUES (71, 'arena-trap', 'generation-iii', 'While this Pokémon is in battle, opposing Pokémon cannot flee or switch out.  Flying-type Pokémon and Pokémon in the air, e.g. due to Levitate or Magnet Rise, are unaffected.  Pokémon with Run Away can still flee.  Pokémon can still switch out with the use of a move or item.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.', 'While this Pokémon is in battle, opposing Pokémon cannot flee or switch out.  Flying-type Pokémon and Pokémon in the air, e.g. due to Levitate or Magnet Rise, are unaffected.  Pokémon with Run Away can still flee.  Pokémon can still switch out with the use of a move or item.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.');
INSERT INTO abilities VALUES (72, 'vital-spirit', 'generation-iii', 'This Pokémon cannot be asleep.  This causes Rest to fail altogether.  If a Pokémon is asleep and acquires this ability, it will immediately wake up; this includes when regaining a lost ability upon leaving battle.  This ability functions identically to Insomnia in battle.  Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.', 'This Pokémon cannot be asleep.  This causes Rest to fail altogether.  If a Pokémon is asleep and acquires this ability, it will immediately wake up; this includes when regaining a lost ability upon leaving battle.  This ability functions identically to Insomnia in battle.  Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.');
INSERT INTO abilities VALUES (73, 'white-smoke', 'generation-iii', 'This Pokémon cannot have its stats lowered by other Pokémon.  This ability does not prevent any stat losses other than stat modifiers, such as the Speed cut from paralysis; nor self-inflicted stat drops, such as the Special Attack drop from Overheat; nor opponent-triggered stat boosts, such as the Attack boost from Swagger.  This Pokémon can still be passed negative stat modifiers through Guard Swap, Heart Swap, or Power Swap.  This ability functions identically to Clear Body in battle.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved.', 'This Pokémon cannot have its stats lowered by other Pokémon.  This ability does not prevent any stat losses other than stat modifiers, such as the Speed cut from paralysis; nor self-inflicted stat drops, such as the Special Attack drop from Overheat; nor opponent-triggered stat boosts, such as the Attack boost from Swagger.  This Pokémon can still be passed negative stat modifiers through Guard Swap, Heart Swap, or Power Swap.  This ability functions identically to Clear Body in battle.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved.');
INSERT INTO abilities VALUES (74, 'pure-power', 'generation-iii', 'This Pokémon''s Attack is doubled in battle.  This bonus does not count as a stat modifier.  This ability functions identically to Huge Power.', 'This Pokémon''s Attack is doubled in battle.  This bonus does not count as a stat modifier.  This ability functions identically to Huge Power.');
INSERT INTO abilities VALUES (75, 'shell-armor', 'generation-iii', 'Moves cannot score critical hits against this Pokémon.  This ability functions identically to Battle Armor.', 'Moves cannot score critical hits against this Pokémon.  This ability functions identically to Battle Armor.');
INSERT INTO abilities VALUES (76, 'air-lock', 'generation-iii', 'While this Pokémon is in battle, weather can still be in play, but will not have any of its effects.  This ability functions identically to Cloud Nine.', 'While this Pokémon is in battle, weather can still be in play, but will not have any of its effects.  This ability functions identically to Cloud Nine.');
INSERT INTO abilities VALUES (77, 'tangled-feet', 'generation-iv', 'When this Pokémon is confused, it has twice its evasion.', 'When this Pokémon is confused, it has twice its evasion.');
INSERT INTO abilities VALUES (78, 'motor-drive', 'generation-iv', 'Whenever an Electric-type move hits this Pokémon, its Speed rises one stage, negating any other effect on it.  This ability will not take effect if this Pokémon is immune to Electric moves.  Electric moves will ignore this Pokémon''s Substitute.  This effect includes non-damaging moves, i.e. Thunder Wave.', 'Whenever an Electric-type move hits this Pokémon, its Speed rises one stage, negating any other effect on it.  This ability will not take effect if this Pokémon is immune to Electric moves.  Electric moves will ignore this Pokémon''s Substitute.  This effect includes non-damaging moves, i.e. Thunder Wave.');
INSERT INTO abilities VALUES (79, 'rivalry', 'generation-iv', 'This Pokémon inflicts 1.25× as much regular damage against Pokémon of the same gender and 0.75× as much regular damage against Pokémon of the opposite gender.  If either Pokémon is genderless, damage is unaffected.', 'This Pokémon inflicts 1.25× as much regular damage against Pokémon of the same gender and 0.75× as much regular damage against Pokémon of the opposite gender.  If either Pokémon is genderless, damage is unaffected.');
INSERT INTO abilities VALUES (80, 'steadfast', 'generation-iv', 'Whenever this Pokémon flinches, its Speed rises one stage.', 'Whenever this Pokémon flinches, its Speed rises one stage.');
INSERT INTO abilities VALUES (81, 'snow-cloak', 'generation-iv', 'During hail, this Pokémon has 1.25× its evasion, and it does not take hail damage regardless of type.  The evasion bonus does not count as a stat modifier.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in snow.', 'During hail, this Pokémon has 1.25× its evasion, and it does not take hail damage regardless of type.  The evasion bonus does not count as a stat modifier.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in snow.');
INSERT INTO abilities VALUES (82, 'gluttony', 'generation-iv', 'This Pokémon eats any held Berry triggered by low HP when it falls below 50% of its HP, regardless of the Berry''s usual threshold.', 'This Pokémon eats any held Berry triggered by low HP when it falls below 50% of its HP, regardless of the Berry''s usual threshold.');
INSERT INTO abilities VALUES (83, 'anger-point', 'generation-iv', 'Whenever this Pokémon receives a critical hit, its Attack rises to the maximum of 6 stages.  This ability will still take effect if the critical hit is received by a Substitute.', 'Whenever this Pokémon receives a critical hit, its Attack rises to the maximum of 6 stages.  This ability will still take effect if the critical hit is received by a Substitute.');
INSERT INTO abilities VALUES (84, 'unburden', 'generation-iv', 'When this Pokémon uses or loses its held item, its Speed is doubled.  If it gains another item or leaves battle, this bonus is lost.  This includes when the Pokémon drops its item because of Knock Off.  This bonus does not count as a stat modifier.  There is no notification when this ability takes effect.', 'When this Pokémon uses or loses its held item, its Speed is doubled.  If it gains another item or leaves battle, this bonus is lost.  This includes when the Pokémon drops its item because of Knock Off.  This bonus does not count as a stat modifier.  There is no notification when this ability takes effect.');
INSERT INTO abilities VALUES (85, 'heatproof', 'generation-iv', 'This Pokémon takes half as much damage from Fire-type moves and burns.', 'This Pokémon takes half as much damage from Fire-type moves and burns.');
INSERT INTO abilities VALUES (86, 'simple', 'generation-iv', 'Each stage of this Pokémon''s stat modifiers acts as two stages.  These doubled stages are still limited to a minimum of -6 and a maximum of 6.  This Pokémon can still accumulate less than -3 or more than 3 stages of stat modifiers, even though the extra ones have no effect after doubling.', 'Each stage of this Pokémon''s stat modifiers acts as two stages.  These doubled stages are still limited to a minimum of -6 and a maximum of 6.  This Pokémon can still accumulate less than -3 or more than 3 stages of stat modifiers, even though the extra ones have no effect after doubling.');
INSERT INTO abilities VALUES (87, 'dry-skin', 'generation-iv', 'This Pokémon takes 1/8 of its maximum HP in damage after each turn during strong sunlight, but it heals for 1/8 of its HP each turn during rain.  This Pokémon takes 1.25× as much damage from Fire-type moves, but whenever a Water move hits it, it heals for 1/4 its maximum HP instead.', 'This Pokémon takes 1/8 of its maximum HP in damage after each turn during strong sunlight, but it heals for 1/8 of its HP each turn during rain.  This Pokémon takes 1.25× as much damage from Fire-type moves, but whenever a Water move hits it, it heals for 1/4 its maximum HP instead.');
INSERT INTO abilities VALUES (88, 'download', 'generation-iv', 'When this Pokémon enters battle, its Attack or Special Attack, whichever corresponds to its opponents'' weaker total defensive stat, rises one stage.  In the event of a tie, Special Attack is raised.  This ability also takes effect when acquired during a battle.', 'When this Pokémon enters battle, its Attack or Special Attack, whichever corresponds to its opponents'' weaker total defensive stat, rises one stage.  In the event of a tie, Special Attack is raised.  This ability also takes effect when acquired during a battle.');
INSERT INTO abilities VALUES (89, 'iron-fist', 'generation-iv', 'Moves flagged as being punch-based have 1.2× their base power for this Pokémon.  Sucker Punch is not flagged as punch-based; its original, Japanese name only means "surprise attack".', 'Moves flagged as being punch-based have 1.2× their base power for this Pokémon.  Sucker Punch is not flagged as punch-based; its original, Japanese name only means "surprise attack".');
INSERT INTO abilities VALUES (90, 'poison-heal', 'generation-iv', 'If this Pokémon is poisoned, it will heal for 1/8 of its maximum HP after each turn rather than taking damage.  This includes bad poison.', 'If this Pokémon is poisoned, it will heal for 1/8 of its maximum HP after each turn rather than taking damage.  This includes bad poison.');
INSERT INTO abilities VALUES (91, 'adaptability', 'generation-iv', 'This Pokémon inflicts twice as much damage with moves whose types match its own, rather than the usual same-type attack bonus of 1.5×.', 'This Pokémon inflicts twice as much damage with moves whose types match its own, rather than the usual same-type attack bonus of 1.5×.');
INSERT INTO abilities VALUES (92, 'skill-link', 'generation-iv', 'This Pokémon always hits five times with two-to-five-hit moves, such as Icicle Spear.  It also bypasses the accuracy checks on Triple Kick''s second and third hits.', 'This Pokémon always hits five times with two-to-five-hit moves, such as Icicle Spear.  It also bypasses the accuracy checks on Triple Kick''s second and third hits.');
INSERT INTO abilities VALUES (93, 'hydration', 'generation-iv', 'This Pokémon is cured of any major status ailment after each turn during rain.', 'This Pokémon is cured of any major status ailment after each turn during rain.');
INSERT INTO abilities VALUES (94, 'solar-power', 'generation-iv', 'During strong sunlight, this Pokémon has 1.5× its Special Attack but takes 1/8 of its maximum HP in damage after each turn.', 'During strong sunlight, this Pokémon has 1.5× its Special Attack but takes 1/8 of its maximum HP in damage after each turn.');
INSERT INTO abilities VALUES (95, 'quick-feet', 'generation-iv', 'Whenever this Pokémon has a major status ailment, it has 1.5× its Speed.  This Pokémon is not affected by the usual Speed cut from paralysis.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved.', 'Whenever this Pokémon has a major status ailment, it has 1.5× its Speed.  This Pokémon is not affected by the usual Speed cut from paralysis.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved.');
INSERT INTO abilities VALUES (96, 'normalize', 'generation-iv', 'This Pokémon''s moves all act as if they were Normal-type.  Moves that inflict typeless damage do so as usual.  Moves of variable type, such as Hidden Power, are affected.  They otherwise work as usual, however; Weather Ball, for example, is always forced to be Normal, but it still has doubled power and looks different during weather.  As Thunder Wave is prevented by immunities, unlike most non-damaging moves, it does not affect Ghost-type Pokémon under the effect of this ability.', 'This Pokémon''s moves all act as if they were Normal-type.  Moves that inflict typeless damage do so as usual.  Moves of variable type, such as Hidden Power, are affected.  They otherwise work as usual, however; Weather Ball, for example, is always forced to be Normal, but it still has doubled power and looks different during weather.  As Thunder Wave is prevented by immunities, unlike most non-damaging moves, it does not affect Ghost-type Pokémon under the effect of this ability.');
INSERT INTO abilities VALUES (97, 'sniper', 'generation-iv', 'This Pokémon inflicts triple damage with critical hits, rather than the usual double damage.', 'This Pokémon inflicts triple damage with critical hits, rather than the usual double damage.');
INSERT INTO abilities VALUES (98, 'magic-guard', 'generation-iv', 'This Pokémon is immune to damage not directly caused by a move.  For example, this Pokémon takes no damage from from weather, recoil, status ailments, or Spikes, but it still suffers from the Attack cut when burned, and a Life Orb will still power up this Pokémon''s moves without damaging it.  Anything that directly depends on such damage will also not happen; for example, Leech Seed will neither hurt this Pokémon nor heal the opponent, and Pokémon with a Jaboca Berry or Rowap Berry will not consume the berry when hit by this Pokémon.  The following are unaffected: Struggle, Pain Split (whether used by or against this Pokémon), Belly Drum, Substitute, Curse, moves that knock the user out, and damage from confusion.  This Pokémon will neither lose nor regain HP if it drains HP from a Pokémon with Liquid Ooze.  If this Pokémon is badly poisoned, the poison counter is still increased each turn; if the Pokémon loses this ability, it will begin taking as much damage as it would be if it had been taking increasing damage each turn.', 'This Pokémon is immune to damage not directly caused by a move.  For example, this Pokémon takes no damage from from weather, recoil, status ailments, or Spikes, but it still suffers from the Attack cut when burned, and a Life Orb will still power up this Pokémon''s moves without damaging it.  Anything that directly depends on such damage will also not happen; for example, Leech Seed will neither hurt this Pokémon nor heal the opponent, and Pokémon with a Jaboca Berry or Rowap Berry will not consume the berry when hit by this Pokémon.  The following are unaffected: Struggle, Pain Split (whether used by or against this Pokémon), Belly Drum, Substitute, Curse, moves that knock the user out, and damage from confusion.  This Pokémon will neither lose nor regain HP if it drains HP from a Pokémon with Liquid Ooze.  If this Pokémon is badly poisoned, the poison counter is still increased each turn; if the Pokémon loses this ability, it will begin taking as much damage as it would be if it had been taking increasing damage each turn.');
INSERT INTO abilities VALUES (99, 'no-guard', 'generation-iv', 'Moves used by or against this Pokémon never miss.  One-hit KO moves are unaffected.  Moves affected by this ability can hit Pokémon during the preparation turn of moves like Dig or Fly.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.', 'Moves used by or against this Pokémon never miss.  One-hit KO moves are unaffected.  Moves affected by this ability can hit Pokémon during the preparation turn of moves like Dig or Fly.  Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.');
INSERT INTO abilities VALUES (100, 'stall', 'generation-iv', 'This Pokémon moves last within its priority bracket.  Multiple Pokémon with this ability move in order of Speed amongst themselves.  The Full Incense and Lagging Tail take precedence over this ability; that is, Pokémon with these items move after Pokémon with this ability.  Pokémon with both this ability and one of these items are delayed as much as if they had only the item.  This ability works as usual during Trick Room: Pokémon with this ability will move in reverse order of Speed after Pokémon without it.', 'This Pokémon moves last within its priority bracket.  Multiple Pokémon with this ability move in order of Speed amongst themselves.  The Full Incense and Lagging Tail take precedence over this ability; that is, Pokémon with these items move after Pokémon with this ability.  Pokémon with both this ability and one of these items are delayed as much as if they had only the item.  This ability works as usual during Trick Room: Pokémon with this ability will move in reverse order of Speed after Pokémon without it.');
INSERT INTO abilities VALUES (101, 'technician', 'generation-iv', 'This Pokémon''s moves have 1.5× their power if their base power is 60 or less.  This includes moves of variable power, such as Hidden Power and Magnitude, when their power is 60 or less.  Helping Hand''s power boost is taken into account for any move, as is Defense Curl''s power boost for Rollout.', 'This Pokémon''s moves have 1.5× their power if their base power is 60 or less.  This includes moves of variable power, such as Hidden Power and Magnitude, when their power is 60 or less.  Helping Hand''s power boost is taken into account for any move, as is Defense Curl''s power boost for Rollout.');
INSERT INTO abilities VALUES (102, 'leaf-guard', 'generation-iv', 'This Pokémon cannot be given a major status ailment during strong sunlight.  This ability does not heal prior status ailments.  Rest will fail altogether with this ability in effect.  Yawn will immediately fail if used on this Pokémon during strong sunlight, and an already-used Yawn will fail if the weather turns to strong sunlight in the meantime.', 'This Pokémon cannot be given a major status ailment during strong sunlight.  This ability does not heal prior status ailments.  Rest will fail altogether with this ability in effect.  Yawn will immediately fail if used on this Pokémon during strong sunlight, and an already-used Yawn will fail if the weather turns to strong sunlight in the meantime.');
INSERT INTO abilities VALUES (103, 'klutz', 'generation-iv', 'In battle, this Pokémon cannot use its held item, nor will the item have any passive effect on the battle, positive or negative.  This Pokémon also cannot use Fling.  The Speed cut from the Iron Ball and the effort items (the Macho Brace, Power Weight, Power Bracer, Power Belt, Power Lens, Power Band, and Power Anklet) is unaffected.  Items that do not directly affect the battle, such as the Exp. Share, the Amulet Coin, or the Soothe Bell, work as usual.  All held items work as usual out of battle.  Other moves that use the held item, such as Natural Gift and Switcheroo, work as usual.', 'In battle, this Pokémon cannot use its held item, nor will the item have any passive effect on the battle, positive or negative.  This Pokémon also cannot use Fling.  The Speed cut from the Iron Ball and the effort items (the Macho Brace, Power Weight, Power Bracer, Power Belt, Power Lens, Power Band, and Power Anklet) is unaffected.  Items that do not directly affect the battle, such as the Exp. Share, the Amulet Coin, or the Soothe Bell, work as usual.  All held items work as usual out of battle.  Other moves that use the held item, such as Natural Gift and Switcheroo, work as usual.');
INSERT INTO abilities VALUES (104, 'mold-breaker', 'generation-iv', 'This Pokémon''s moves completely ignore abilities that could hinder or prevent their effect on the target.  For example, this Pokémon''s moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat.  If an ability could either hinder or help this Pokémon''s moves, e.g. Dry Skin or Unaware, the ability is ignored either way.  Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected.  For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move''s effect on the user.  This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle.  This ability cannot ignore Multitype at all.  An ability ignored by this ability is only nullified while the move is being used.  For example, this Pokémon''s moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon''s Spikes are not affected by this ability after they have been placed.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  This ability functions identically to Teravolt and Turboblaze.', 'This Pokémon''s moves completely ignore abilities that could hinder or prevent their effect on the target.  For example, this Pokémon''s moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat.  If an ability could either hinder or help this Pokémon''s moves, e.g. Dry Skin or Unaware, the ability is ignored either way.  Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected.  For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move''s effect on the user.  This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle.  This ability cannot ignore Multitype at all.  An ability ignored by this ability is only nullified while the move is being used.  For example, this Pokémon''s moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon''s Spikes are not affected by this ability after they have been placed.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  This ability functions identically to Teravolt and Turboblaze.');
INSERT INTO abilities VALUES (105, 'super-luck', 'generation-iv', 'This Pokémon''s moves have critical hit rates one stage higher than normal.', 'This Pokémon''s moves have critical hit rates one stage higher than normal.');
INSERT INTO abilities VALUES (106, 'aftermath', 'generation-iv', 'When this Pokémon is knocked out by a move that makes contact, the move''s user takes 1/4 its maximum HP in damage.', 'When this Pokémon is knocked out by a move that makes contact, the move''s user takes 1/4 its maximum HP in damage.');
INSERT INTO abilities VALUES (107, 'anticipation', 'generation-iv', 'When this Pokémon enters battle, if one of its opponents has a move that is super effective against it, Self-Destruct, Explosion, or a one-hit knockout move, all participating trainers are notified.  The move itself is not revealed; only that there is such a move.  Moves that inflict typeless damage, such as Future Sight, and moves of variable type, such as Hidden Power, count as their listed types.  Counter, Metal Burst, Mirror Coat, and one-hit KO moves to which this Pokémon is immune do not trigger this ability.', 'When this Pokémon enters battle, if one of its opponents has a move that is super effective against it, Self-Destruct, Explosion, or a one-hit knockout move, all participating trainers are notified.  The move itself is not revealed; only that there is such a move.  Moves that inflict typeless damage, such as Future Sight, and moves of variable type, such as Hidden Power, count as their listed types.  Counter, Metal Burst, Mirror Coat, and one-hit KO moves to which this Pokémon is immune do not trigger this ability.');
INSERT INTO abilities VALUES (108, 'forewarn', 'generation-iv', 'When this Pokémon enters battle, it reveals the move with the highest base power known by any opposing Pokémon to all participating trainers.  In the event of a tie, one is chosen at random.  Moves without a listed base power are assigned one as follows:  Power | Moves ----: | -----   160 | One-hit KO moves: Fissure, Guillotine, Horn Drill, and Sheer Cold   120 | Counter moves: Counter, Metal Burst, and Mirror Coat    80 | Variable power or set damage: Crush Grip, Dragon Rage, Electro Ball, Endeavor, Final Gambit, Flail, Frustration, Grass Knot, Gyro Ball, Heat Crash, Heavy Slam, Hidden Power, Low Kick, Natural Gift, Night Shade, Psywave, Return, Reversal, Seismic Toss, Sonic Boom, Trump Card, and Wring Out     0 | Any such move not listed ', 'When this Pokémon enters battle, it reveals the move with the highest base power known by any opposing Pokémon to all participating trainers.  In the event of a tie, one is chosen at random.  Moves without a listed base power are assigned one as follows:  Power | Moves ----: | -----   160 | One-hit KO moves: Fissure, Guillotine, Horn Drill, and Sheer Cold   120 | Counter moves: Counter, Metal Burst, and Mirror Coat    80 | Variable power or set damage: Crush Grip, Dragon Rage, Electro Ball, Endeavor, Final Gambit, Flail, Frustration, Grass Knot, Gyro Ball, Heat Crash, Heavy Slam, Hidden Power, Low Kick, Natural Gift, Night Shade, Psywave, Return, Reversal, Seismic Toss, Sonic Boom, Trump Card, and Wring Out     0 | Any such move not listed ');
INSERT INTO abilities VALUES (109, 'unaware', 'generation-iv', 'This Pokémon ignores other Pokémon''s stat modifiers for the purposes of damage and accuracy calculation.  Effectively, this affects modifiers of every stat except Speed.  The power of Punishment and Stored Power is calculated as usual.  When this Pokémon hurts itself in confusion, its stat modifiers affect damage as usual.', 'This Pokémon ignores other Pokémon''s stat modifiers for the purposes of damage and accuracy calculation.  Effectively, this affects modifiers of every stat except Speed.  The power of Punishment and Stored Power is calculated as usual.  When this Pokémon hurts itself in confusion, its stat modifiers affect damage as usual.');
INSERT INTO abilities VALUES (110, 'tinted-lens', 'generation-iv', 'This Pokémon deals twice as much damage with moves that are not very effective against the target.', 'This Pokémon deals twice as much damage with moves that are not very effective against the target.');
INSERT INTO abilities VALUES (111, 'filter', 'generation-iv', 'This Pokémon takes 0.75× as much damage from moves that are super effective against it.  This ability functions identically to Solid Rock.', 'This Pokémon takes 0.75× as much damage from moves that are super effective against it.  This ability functions identically to Solid Rock.');
INSERT INTO abilities VALUES (112, 'slow-start', 'generation-iv', 'This Pokémon''s Attack and Speed are halved for five turns upon entering battle.  This ability also takes effect when acquired during battle.  If this Pokémon loses its ability before the five turns are up, its Attack and Speed return to normal; if it then regains this ability without leaving battle, its Attack and Speed are halved again, but the counter keeps counting from where it was.', 'This Pokémon''s Attack and Speed are halved for five turns upon entering battle.  This ability also takes effect when acquired during battle.  If this Pokémon loses its ability before the five turns are up, its Attack and Speed return to normal; if it then regains this ability without leaving battle, its Attack and Speed are halved again, but the counter keeps counting from where it was.');
INSERT INTO abilities VALUES (113, 'scrappy', 'generation-iv', 'This Pokémon ignores Ghost-type Pokémon''s immunity to Normal- and Fighting-type moves.  Ghost Pokémon''s other types affect damage as usual.', 'This Pokémon ignores Ghost-type Pokémon''s immunity to Normal- and Fighting-type moves.  Ghost Pokémon''s other types affect damage as usual.');
INSERT INTO abilities VALUES (114, 'storm-drain', 'generation-iv', 'All other Pokémon''s single-target Water-type moves are redirected to this Pokémon, if it is an eligible target.  Other Pokémon''s Water moves raise this Pokémon''s Special Attack one stage, negating any other effect on it, and cannot miss it.  If the move''s intended target also has this ability, the move is not redirected.  When multiple Pokémon with this ability are possible targets for redirection, the move is redirected to the one with the highest Speed stat, or, in the case of a tie, to a random tied Pokémon.  Follow Me takes precedence over this ability.', 'All other Pokémon''s single-target Water-type moves are redirected to this Pokémon, if it is an eligible target.  Other Pokémon''s Water moves raise this Pokémon''s Special Attack one stage, negating any other effect on it, and cannot miss it.  If the move''s intended target also has this ability, the move is not redirected.  When multiple Pokémon with this ability are possible targets for redirection, the move is redirected to the one with the highest Speed stat, or, in the case of a tie, to a random tied Pokémon.  Follow Me takes precedence over this ability.');
INSERT INTO abilities VALUES (115, 'ice-body', 'generation-iv', 'This Pokémon heals for 1/16 of its maximum HP after each turn during hail, and it does not take hail damage regardless of type.', 'This Pokémon heals for 1/16 of its maximum HP after each turn during hail, and it does not take hail damage regardless of type.');
INSERT INTO abilities VALUES (116, 'solid-rock', 'generation-iv', 'This Pokémon takes 0.75× as much damage from moves that are super effective against it.  This ability functions identically to Filter.', 'This Pokémon takes 0.75× as much damage from moves that are super effective against it.  This ability functions identically to Filter.');
INSERT INTO abilities VALUES (117, 'snow-warning', 'generation-iv', 'The weather changes to hail when this Pokémon enters battle and does not end unless cancelled by another weather condition.  If multiple Pokémon with this ability, Drizzle, Drought, or Sand Stream are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.', 'The weather changes to hail when this Pokémon enters battle and does not end unless cancelled by another weather condition.  If multiple Pokémon with this ability, Drizzle, Drought, or Sand Stream are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room.  Each ability''s weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.');
INSERT INTO abilities VALUES (118, 'honey-gather', 'generation-iv', 'This Pokémon has a chance of picking up Honey after each battle.  This chance starts at 5% and rises another 5% after every tenth level: 5% from level 1–10, 10% from 11–20, and so on, up to 50% from 91–100.  This ability is checked after the battle ends, at which point any temporary ability changes have worn off.', 'This Pokémon has a chance of picking up Honey after each battle.  This chance starts at 5% and rises another 5% after every tenth level: 5% from level 1–10, 10% from 11–20, and so on, up to 50% from 91–100.  This ability is checked after the battle ends, at which point any temporary ability changes have worn off.');
INSERT INTO abilities VALUES (119, 'frisk', 'generation-iv', 'When this Pokémon enters battle, it reveals an opposing Pokémon''s held item to all participating trainers.  In a double battle, if one opponent has an item, this Pokémon will Frisk that Pokémon; if both have an item, it will Frisk one at random.', 'When this Pokémon enters battle, it reveals an opposing Pokémon''s held item to all participating trainers.  In a double battle, if one opponent has an item, this Pokémon will Frisk that Pokémon; if both have an item, it will Frisk one at random.');
INSERT INTO abilities VALUES (120, 'reckless', 'generation-iv', 'This Pokémon''s recoil moves and crash moves have 1.2× their base power.  Struggle is unaffected.  The "crash moves" are the moves that damage the user upon missing: Jump Kick and High Jump Kick.', 'This Pokémon''s recoil moves and crash moves have 1.2× their base power.  Struggle is unaffected.  The "crash moves" are the moves that damage the user upon missing: Jump Kick and High Jump Kick.');
INSERT INTO abilities VALUES (121, 'multitype', 'generation-iv', 'If this Pokémon is holding an elemental Plate, its type and form change to match the Plate.  This Pokémon''s held item, whether or not it is a Plate, cannot be taken by Covet or Thief, nor removed by Knock Off, nor traded by Switcheroo or Trick.  Covet, Thief, and Knock Off still inflict damage against this Pokémon.  Unlike with Sticky Hold, this Pokémon cannot use Fling, Switcheroo, or Trick to lose its item itself, nor gain an item through Switcheroo or Trick if it does not have one.  This ability has no effect for any Pokémon other than Arceus.  This ability cannot be traded with Skill Swap, nor copied with Role Play or Trace, nor disabled with Gastro Acid, nor changed with Worry Seed.  This Pokémon cannot use Skill Swap or Role Play to lose its ability itself.  Mold Breaker cannot ignore this ability.  If a Pokémon Transforms into an Arceus with this ability, it will Transform into Arceus''s default, Normal-type form.  If the Transforming Pokémon is holding a Plate, this ability will then activate and change the Pokémon into the corresponding form.', 'If this Pokémon is holding an elemental Plate, its type and form change to match the Plate.  This Pokémon''s held item, whether or not it is a Plate, cannot be taken by Covet or Thief, nor removed by Knock Off, nor traded by Switcheroo or Trick.  Covet, Thief, and Knock Off still inflict damage against this Pokémon.  Unlike with Sticky Hold, this Pokémon cannot use Fling, Switcheroo, or Trick to lose its item itself, nor gain an item through Switcheroo or Trick if it does not have one.  This ability has no effect for any Pokémon other than Arceus.  This ability cannot be traded with Skill Swap, nor copied with Role Play or Trace, nor disabled with Gastro Acid, nor changed with Worry Seed.  This Pokémon cannot use Skill Swap or Role Play to lose its ability itself.  Mold Breaker cannot ignore this ability.  If a Pokémon Transforms into an Arceus with this ability, it will Transform into Arceus''s default, Normal-type form.  If the Transforming Pokémon is holding a Plate, this ability will then activate and change the Pokémon into the corresponding form.');
INSERT INTO abilities VALUES (122, 'flower-gift', 'generation-iv', 'Friendly Pokémon have 1.5× their Attack and Special Defense during strong sunlight if any friendly Pokémon has this ability.  Unlike Forecast, Multitype, and Zen Mode, this ability is not tied to its Pokémon''s form change; Cherrim will switch between its forms even if it loses this ability.  As such, this ability also works if obtained by a Pokémon other than Cherrim.', 'Friendly Pokémon have 1.5× their Attack and Special Defense during strong sunlight if any friendly Pokémon has this ability.  Unlike Forecast, Multitype, and Zen Mode, this ability is not tied to its Pokémon''s form change; Cherrim will switch between its forms even if it loses this ability.  As such, this ability also works if obtained by a Pokémon other than Cherrim.');
INSERT INTO abilities VALUES (123, 'bad-dreams', 'generation-iv', 'Opposing Pokémon take 1/8 of their maximum HP in damage after each turn while they are asleep.', 'Opposing Pokémon take 1/8 of their maximum HP in damage after each turn while they are asleep.');
INSERT INTO abilities VALUES (124, 'pickpocket', 'generation-v', 'Whenever a move makes contact with this Pokémon, if it does not have a held item, it steals the attacker''s held item.  This Pokémon cannot steal upon being knocked out.  It can steal if the attacker has a Substitute, but cannot steal when its own Substitute is hit.  If a move hits multiple times, only the last hit triggers this ability.  If this Pokémon is wild, it cannot steal from a trained Pokémon.', 'Whenever a move makes contact with this Pokémon, if it does not have a held item, it steals the attacker''s held item.  This Pokémon cannot steal upon being knocked out.  It can steal if the attacker has a Substitute, but cannot steal when its own Substitute is hit.  If a move hits multiple times, only the last hit triggers this ability.  If this Pokémon is wild, it cannot steal from a trained Pokémon.');
INSERT INTO abilities VALUES (125, 'sheer-force', 'generation-v', 'This Pokémon''s moves with extra effects have 1.3× their power, but lose their extra effects.  An effect chance is a move''s chance to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move''s main effect. For example, Thunder Shock''s paralysis is an extra effect, but Thunder Wave''s is not, nor are Knock Off''s item removal and Air Cutter''s increased critical hit rate.  Moves that lower the user''s stats are unaffected.', 'This Pokémon''s moves with extra effects have 1.3× their power, but lose their extra effects.  An effect chance is a move''s chance to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move''s main effect. For example, Thunder Shock''s paralysis is an extra effect, but Thunder Wave''s is not, nor are Knock Off''s item removal and Air Cutter''s increased critical hit rate.  Moves that lower the user''s stats are unaffected.');
INSERT INTO abilities VALUES (126, 'contrary', 'generation-v', 'Whenever this Pokémon''s stats would be raised, they are instead lowered by the same amount, and vice versa.', 'Whenever this Pokémon''s stats would be raised, they are instead lowered by the same amount, and vice versa.');
INSERT INTO abilities VALUES (127, 'unnerve', 'generation-v', 'Opposing Pokémon cannot eat held Berries while this Pokémon is in battle.  Affected Pokémon can still use Bug Bite or Pluck to eat a target''s Berry.', 'Opposing Pokémon cannot eat held Berries while this Pokémon is in battle.  Affected Pokémon can still use Bug Bite or Pluck to eat a target''s Berry.');
INSERT INTO abilities VALUES (128, 'defiant', 'generation-v', 'When any of this Pokémon''s stats are lowered, its Attack rises by two stages.  If multiple stats are lowered at once, this ability takes effect with each stat lowered.', 'When any of this Pokémon''s stats are lowered, its Attack rises by two stages.  If multiple stats are lowered at once, this ability takes effect with each stat lowered.');
INSERT INTO abilities VALUES (129, 'defeatist', 'generation-v', 'This Pokémon''s Attack and Special Attack are halved when it has half its HP or less.', 'This Pokémon''s Attack and Special Attack are halved when it has half its HP or less.');
INSERT INTO abilities VALUES (130, 'cursed-body', 'generation-v', 'Moves that hit this Pokémon have a 30% chance of being Disabled afterward.', 'Moves that hit this Pokémon have a 30% chance of being Disabled afterward.');
INSERT INTO abilities VALUES (131, 'healer', 'generation-v', 'Friendly Pokémon next to this Pokémon in double and triple battles each have a 30% chance of being cured of any major status ailment after each turn.', 'Friendly Pokémon next to this Pokémon in double and triple battles each have a 30% chance of being cured of any major status ailment after each turn.');
INSERT INTO abilities VALUES (132, 'friend-guard', 'generation-v', 'All friendly Pokémon take 0.75× as much direct damage from moves while this Pokémon is in battle.  This effect stacks if multiple allied Pokémon have it.', 'All friendly Pokémon take 0.75× as much direct damage from moves while this Pokémon is in battle.  This effect stacks if multiple allied Pokémon have it.');
INSERT INTO abilities VALUES (133, 'weak-armor', 'generation-v', 'Whenever a physical move hits this Pokémon, its Speed rises one stage and its Defense falls one stage.  This ability triggers on every hit of a multiple-hit move.', 'Whenever a physical move hits this Pokémon, its Speed rises one stage and its Defense falls one stage.  This ability triggers on every hit of a multiple-hit move.');
INSERT INTO abilities VALUES (134, 'heavy-metal', 'generation-v', 'This Pokémon has double the usual weight for its species.', 'This Pokémon has double the usual weight for its species.');
INSERT INTO abilities VALUES (135, 'light-metal', 'generation-v', 'This Pokémon has half the usual weight for its species.', 'This Pokémon has half the usual weight for its species.');
INSERT INTO abilities VALUES (136, 'multiscale', 'generation-v', 'This Pokémon takes half as much damage when it is hit having full HP.', 'This Pokémon takes half as much damage when it is hit having full HP.');
INSERT INTO abilities VALUES (137, 'toxic-boost', 'generation-v', 'This Pokémon has 1.5× its Attack when poisoned.', 'This Pokémon has 1.5× its Attack when poisoned.');
INSERT INTO abilities VALUES (138, 'flare-boost', 'generation-v', 'This Pokémon has 1.5× its Special Attack when burned.', 'This Pokémon has 1.5× its Special Attack when burned.');
INSERT INTO abilities VALUES (139, 'harvest', 'generation-v', 'After each turn, if the last item this Pokémon consumed was a Berry and it is not currently holding an item, it has a 50% chance of regaining that Berry, or a 100% chance during strong sunlight.', 'After each turn, if the last item this Pokémon consumed was a Berry and it is not currently holding an item, it has a 50% chance of regaining that Berry, or a 100% chance during strong sunlight.');
INSERT INTO abilities VALUES (140, 'telepathy', 'generation-v', 'This Pokémon does not take damage from friendly Pokémon''s moves, including single-target moves aimed at it.', 'This Pokémon does not take damage from friendly Pokémon''s moves, including single-target moves aimed at it.');
INSERT INTO abilities VALUES (141, 'moody', 'generation-v', 'After each turn, one of this Pokémon''s stats at random rises two stages, and another falls one stage.  If a stat is already at 6 or -6 stages, it will not be chosen to be increased or decreased, respectively.', 'After each turn, one of this Pokémon''s stats at random rises two stages, and another falls one stage.  If a stat is already at 6 or -6 stages, it will not be chosen to be increased or decreased, respectively.');
INSERT INTO abilities VALUES (142, 'overcoat', 'generation-v', 'This Pokémon does not take damage from weather.', 'This Pokémon does not take damage from weather.');
INSERT INTO abilities VALUES (143, 'poison-touch', 'generation-v', 'This Pokémon''s contact moves have a 30% chance of poisoning the target with each hit.  This counts as an extra effect for the purposes of Shield Dust.  This ability takes effect before Mummy.', 'This Pokémon''s contact moves have a 30% chance of poisoning the target with each hit.  This counts as an extra effect for the purposes of Shield Dust.  This ability takes effect before Mummy.');
INSERT INTO abilities VALUES (144, 'regenerator', 'generation-v', 'This Pokémon regains 1/3 of its maximum HP when it is switched out for another Pokémon under any circumstances other than having fainted.  This ability does not take effect when a battle ends.', 'This Pokémon regains 1/3 of its maximum HP when it is switched out for another Pokémon under any circumstances other than having fainted.  This ability does not take effect when a battle ends.');
INSERT INTO abilities VALUES (145, 'big-pecks', 'generation-v', 'This Pokémon''s Defense cannot be lowered by other Pokémon.  This Pokémon can still be passed negative Defense modifiers through Heart Swap or Guard Swap.', 'This Pokémon''s Defense cannot be lowered by other Pokémon.  This Pokémon can still be passed negative Defense modifiers through Heart Swap or Guard Swap.');
INSERT INTO abilities VALUES (146, 'sand-rush', 'generation-v', 'This Pokémon''s Speed is doubled during a sandstorm, and it does not take sandstorm damage, regardless of type.', 'This Pokémon''s Speed is doubled during a sandstorm, and it does not take sandstorm damage, regardless of type.');
INSERT INTO abilities VALUES (147, 'wonder-skin', 'generation-v', 'Non-damaging moves have exactly 50% base accuracy against this Pokémon.', 'Non-damaging moves have exactly 50% base accuracy against this Pokémon.');
INSERT INTO abilities VALUES (148, 'analytic', 'generation-v', 'This Pokémon''s moves have 1.3× their power when it moves last in a turn.  Future Sight and Doom Desire are unaffected.', 'This Pokémon''s moves have 1.3× their power when it moves last in a turn.  Future Sight and Doom Desire are unaffected.');
INSERT INTO abilities VALUES (149, 'illusion', 'generation-v', 'This Pokémon, upon being sent out, appears to have the species, nickname, and Poké Ball of the last Pokémon in the party that is able to battle.  This illusion breaks upon being hit by a damaging move.  Other damage, e.g. from weather or Spikes, does not break the illusion, nor does damage done to a Substitute.  If the party order becomes temporarily shuffled around as Pokémon are switched out in battle, this ability chooses the last Pokémon according to that shuffled order.', 'This Pokémon, upon being sent out, appears to have the species, nickname, and Poké Ball of the last Pokémon in the party that is able to battle.  This illusion breaks upon being hit by a damaging move.  Other damage, e.g. from weather or Spikes, does not break the illusion, nor does damage done to a Substitute.  If the party order becomes temporarily shuffled around as Pokémon are switched out in battle, this ability chooses the last Pokémon according to that shuffled order.');
INSERT INTO abilities VALUES (150, 'imposter', 'generation-v', 'This Pokémon transforms into a random opponent upon entering battle.  This effect is identical to the move Transform.', 'This Pokémon transforms into a random opponent upon entering battle.  This effect is identical to the move Transform.');
INSERT INTO abilities VALUES (151, 'infiltrator', 'generation-v', 'This Pokémon''s moves ignore Light Screen, Reflect, and Safeguard.', 'This Pokémon''s moves ignore Light Screen, Reflect, and Safeguard.');
INSERT INTO abilities VALUES (152, 'mummy', 'generation-v', 'Whenever a contact move hits this Pokémon, the attacking Pokémon''s ability changes to Mummy.  Multitype is unaffected.  If a Pokémon with Moxie knocks this Pokémon out, the former''s ability will change without taking effect.', 'Whenever a contact move hits this Pokémon, the attacking Pokémon''s ability changes to Mummy.  Multitype is unaffected.  If a Pokémon with Moxie knocks this Pokémon out, the former''s ability will change without taking effect.');
INSERT INTO abilities VALUES (153, 'moxie', 'generation-v', 'This Pokémon''s Attack rises one stage upon knocking out another Pokémon, even a friendly Pokémon.  This ability does not take effect when the Pokémon indirectly causes another Pokémon to faint, e.g. through poison or Spikes.  If this Pokémon knocks out a Pokémon with Mummy, the former''s ability will change without taking effect.', 'This Pokémon''s Attack rises one stage upon knocking out another Pokémon, even a friendly Pokémon.  This ability does not take effect when the Pokémon indirectly causes another Pokémon to faint, e.g. through poison or Spikes.  If this Pokémon knocks out a Pokémon with Mummy, the former''s ability will change without taking effect.');
INSERT INTO abilities VALUES (154, 'justified', 'generation-v', 'Whenever a Dark-type move hits this Pokémon, its Attack rises one stage.  The move is not negated in any way.', 'Whenever a Dark-type move hits this Pokémon, its Attack rises one stage.  The move is not negated in any way.');
INSERT INTO abilities VALUES (155, 'rattled', 'generation-v', 'This Pokémon''s Speed rises one stage with each hit from a damaging Dark-, Ghost-, or Bug-type move.', 'This Pokémon''s Speed rises one stage with each hit from a damaging Dark-, Ghost-, or Bug-type move.');
INSERT INTO abilities VALUES (156, 'magic-bounce', 'generation-v', 'When this Pokémon is targeted by a move flagged as being reflectable, the move is redirected to its user.  All reflectable moves are non-damaging, and most non-damaging moves that target other Pokémon are reflectable.  A move reflected by this ability or Magic Coat cannot be reflected back.', 'When this Pokémon is targeted by a move flagged as being reflectable, the move is redirected to its user.  All reflectable moves are non-damaging, and most non-damaging moves that target other Pokémon are reflectable.  A move reflected by this ability or Magic Coat cannot be reflected back.');
INSERT INTO abilities VALUES (157, 'sap-sipper', 'generation-v', 'Whenever a Grass-type move hits this Pokémon, its Attack rises one stage, negating any other effect on it.', 'Whenever a Grass-type move hits this Pokémon, its Attack rises one stage, negating any other effect on it.');
INSERT INTO abilities VALUES (158, 'prankster', 'generation-v', 'This Pokémon''s non-damaging moves have their priority increased by one stage.', 'This Pokémon''s non-damaging moves have their priority increased by one stage.');
INSERT INTO abilities VALUES (159, 'sand-force', 'generation-v', 'During a sandstorm, this Pokémon''s Rock-, Ground-, and Steel-type moves have 1.3× their base power.  This Pokémon does not take sandstorm damage, regardless of type.', 'During a sandstorm, this Pokémon''s Rock-, Ground-, and Steel-type moves have 1.3× their base power.  This Pokémon does not take sandstorm damage, regardless of type.');
INSERT INTO abilities VALUES (160, 'iron-barbs', 'generation-v', 'Whenever a move makes contact with this Pokémon, the move''s user takes 1/8 of its maximum HP in damage.  This ability functions identically to Rough Skin.', 'Whenever a move makes contact with this Pokémon, the move''s user takes 1/8 of its maximum HP in damage.  This ability functions identically to Rough Skin.');
INSERT INTO abilities VALUES (161, 'zen-mode', 'generation-v', 'This Pokémon switches between Standard Mode and Zen Mode after each turn depending on its HP.  Below 50% of its maximum HP, it switches to Zen Mode, and at 50% or above, it switches to Standard Mode.  This Pokémon returns to Standard Mode upon leaving battle or losing this ability.  This ability has no effect if this Pokémon is not a Darmanitan.', 'This Pokémon switches between Standard Mode and Zen Mode after each turn depending on its HP.  Below 50% of its maximum HP, it switches to Zen Mode, and at 50% or above, it switches to Standard Mode.  This Pokémon returns to Standard Mode upon leaving battle or losing this ability.  This ability has no effect if this Pokémon is not a Darmanitan.');
INSERT INTO abilities VALUES (162, 'victory-star', 'generation-v', 'All friendly Pokémon''s moves, including this Pokémon''s own moves, have 1.1× their usual accuracy while this Pokémon is in battle.', 'All friendly Pokémon''s moves, including this Pokémon''s own moves, have 1.1× their usual accuracy while this Pokémon is in battle.');
INSERT INTO abilities VALUES (163, 'turboblaze', 'generation-v', 'This Pokémon''s moves completely ignore abilities that could hinder or prevent their effect on the target.  For example, this Pokémon''s moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat.  If an ability could either hinder or help this Pokémon''s moves, e.g. Dry Skin or Unaware, the ability is ignored either way.  Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected.  For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move''s effect on the user.  This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle.  This ability cannot ignore Multitype at all.  An ability ignored by this ability is only nullified while the move is being used.  For example, this Pokémon''s moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon''s Spikes are not affected by this ability after they have been placed.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  This ability functions identically to Mold Breaker and Teravolt.', 'This Pokémon''s moves completely ignore abilities that could hinder or prevent their effect on the target.  For example, this Pokémon''s moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat.  If an ability could either hinder or help this Pokémon''s moves, e.g. Dry Skin or Unaware, the ability is ignored either way.  Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected.  For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move''s effect on the user.  This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle.  This ability cannot ignore Multitype at all.  An ability ignored by this ability is only nullified while the move is being used.  For example, this Pokémon''s moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon''s Spikes are not affected by this ability after they have been placed.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  This ability functions identically to Mold Breaker and Teravolt.');
INSERT INTO abilities VALUES (164, 'teravolt', 'generation-v', 'This Pokémon''s moves completely ignore abilities that could hinder or prevent their effect on the target.  For example, this Pokémon''s moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat.  If an ability could either hinder or help this Pokémon''s moves, e.g. Dry Skin or Unaware, the ability is ignored either way.  Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected.  For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move''s effect on the user.  This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle.  This ability cannot ignore Multitype at all.  An ability ignored by this ability is only nullified while the move is being used.  For example, this Pokémon''s moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon''s Spikes are not affected by this ability after they have been placed.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  This ability functions identically to Mold Breaker and Turboblaze.', 'This Pokémon''s moves completely ignore abilities that could hinder or prevent their effect on the target.  For example, this Pokémon''s moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat.  If an ability could either hinder or help this Pokémon''s moves, e.g. Dry Skin or Unaware, the ability is ignored either way.  Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected.  For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move''s effect on the user.  This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle.  This ability cannot ignore Multitype at all.  An ability ignored by this ability is only nullified while the move is being used.  For example, this Pokémon''s moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon''s Spikes are not affected by this ability after they have been placed.  When this Pokémon enters battle, all participating trainers are notified that it has this ability.  This ability functions identically to Mold Breaker and Turboblaze.');
INSERT INTO abilities VALUES (165, 'aroma-veil', 'generation-vi', 'Protects allies against moves that affect their mental state.', 'Protects allies against moves that affect their mental state.');
INSERT INTO abilities VALUES (166, 'flower-veil', 'generation-vi', 'Protects friendly Grass Pokémon from having their stats lowered by other Pokémon.', 'Protects friendly Grass Pokémon from having their stats lowered by other Pokémon.');
INSERT INTO abilities VALUES (167, 'cheek-pouch', 'generation-vi', 'Restores HP upon eating a Berry, in addition to the Berry''s effect.', 'Restores HP upon eating a Berry, in addition to the Berry''s effect.');
INSERT INTO abilities VALUES (168, 'protean', 'generation-vi', 'Changes the bearer''s type to match each move it uses.  The type change takes place just before the move is used.', 'Changes the bearer''s type to match each move it uses.  The type change takes place just before the move is used.');
INSERT INTO abilities VALUES (169, 'fur-coat', 'generation-vi', 'Halves damage from physical attacks.', 'Halves damage from physical attacks.');
INSERT INTO abilities VALUES (170, 'magician', 'generation-vi', 'Steals the target''s held item when the bearer uses a damaging move.', 'Steals the target''s held item when the bearer uses a damaging move.');
INSERT INTO abilities VALUES (171, 'bulletproof', 'generation-vi', 'Protects against bullet, ball, and bomb-based moves.', 'Protects against bullet, ball, and bomb-based moves.');
INSERT INTO abilities VALUES (172, 'competitive', 'generation-vi', 'Raises Special Attack by two stages upon having any stat lowered.', 'Raises Special Attack by two stages upon having any stat lowered.');
INSERT INTO abilities VALUES (173, 'strong-jaw', 'generation-vi', 'Strengthens biting moves to 1.5× their power.', 'Strengthens biting moves to 1.5× their power.');
INSERT INTO abilities VALUES (174, 'refrigerate', 'generation-vi', 'Turns the bearer''s Normal-type moves into Ice-type moves.  Moves changed by this ability have 1.3× their power.', 'Turns the bearer''s Normal-type moves into Ice-type moves.  Moves changed by this ability have 1.3× their power.');
INSERT INTO abilities VALUES (175, 'sweet-veil', 'generation-vi', 'Prevents friendly Pokémon from sleeping.', 'Prevents friendly Pokémon from sleeping.');
INSERT INTO abilities VALUES (176, 'stance-change', 'generation-vi', 'Changes Aegislash to Blade Forme before using a damaging move, or Shield Forme before using King’s Shield.', 'Changes Aegislash to Blade Forme before using a damaging move, or Shield Forme before using King’s Shield.');
INSERT INTO abilities VALUES (177, 'gale-wings', 'generation-vi', 'Raises Flying moves'' priority by one stage.', 'Raises Flying moves'' priority by one stage.');
INSERT INTO abilities VALUES (178, 'mega-launcher', 'generation-vi', 'Strengthens aura and pulse moves to 1.5× their power.', 'Strengthens aura and pulse moves to 1.5× their power.');
INSERT INTO abilities VALUES (179, 'grass-pelt', 'generation-vi', 'Boosts Defense while Grassy Terrain is in effect.', 'Boosts Defense while Grassy Terrain is in effect.');
INSERT INTO abilities VALUES (180, 'symbiosis', 'generation-vi', 'Passes the bearer''s held item to an ally when the ally uses up its item.', 'Passes the bearer''s held item to an ally when the ally uses up its item.');
INSERT INTO abilities VALUES (181, 'tough-claws', 'generation-vi', 'Strengthens moves that make contact to 1.33× their power.', 'Strengthens moves that make contact to 1.33× their power.');
INSERT INTO abilities VALUES (182, 'pixilate', 'generation-vi', 'Turns the bearer''s Normal-type moves into Fairy moves.  Moves changed by this ability have 1.3× their power.', 'Turns the bearer''s Normal-type moves into Fairy moves.  Moves changed by this ability have 1.3× their power.');
INSERT INTO abilities VALUES (183, 'gooey', 'generation-vi', 'Lowers attacking Pokémon''s Speed by one stage on contact.', 'Lowers attacking Pokémon''s Speed by one stage on contact.');
INSERT INTO abilities VALUES (184, 'aerilate', 'generation-vi', 'Turns the bearer''s Normal-type moves into Flying-type moves.  Moves changed by this ability have 1.3× their power.', 'Turns the bearer''s Normal-type moves into Flying-type moves.  Moves changed by this ability have 1.3× their power.');
INSERT INTO abilities VALUES (185, 'parental-bond', 'generation-vi', 'Lets the bearer hit twice with damaging moves.  The second hit has half power.', 'Lets the bearer hit twice with damaging moves.  The second hit has half power.');
INSERT INTO abilities VALUES (186, 'dark-aura', 'generation-vi', 'Strengthens Dark moves for all friendly and opposing Pokémon.', 'Strengthens Dark moves for all friendly and opposing Pokémon.');
INSERT INTO abilities VALUES (187, 'fairy-aura', 'generation-vi', 'Strengthens Fairy moves for all friendly and opposing Pokémon.', 'Strengthens Fairy moves for all friendly and opposing Pokémon.');
INSERT INTO abilities VALUES (188, 'aura-break', 'generation-vi', 'While this Pokémon is on the field, Dark Aura and Fairy Aura weaken moves of their respective types to 2/3 their power, rather than strengthening them.', 'While this Pokémon is on the field, Dark Aura and Fairy Aura weaken moves of their respective types to 2/3 their power, rather than strengthening them.');
INSERT INTO abilities VALUES (189, 'primordial-sea', 'generation-vi', 'When this Pokémon enters battle or gains this ability, the weather becomes heavy rain.  Heavy rain has all the properties of Rain Dance and also causes damaging Fire moves to fail.  Heavy rain ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified.  The weather cannot otherwise be changed except by the effects of Delta Stream and Desolate Land.  Air Lock and Cloud Nine will prevent the effects of heavy rain, including allowing Fire moves to work, but will not allow the weather to be changed.', 'When this Pokémon enters battle or gains this ability, the weather becomes heavy rain.  Heavy rain has all the properties of Rain Dance and also causes damaging Fire moves to fail.  Heavy rain ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified.  The weather cannot otherwise be changed except by the effects of Delta Stream and Desolate Land.  Air Lock and Cloud Nine will prevent the effects of heavy rain, including allowing Fire moves to work, but will not allow the weather to be changed.');
INSERT INTO abilities VALUES (190, 'desolate-land', 'generation-vi', 'When this Pokémon enters battle or gains this ability, the weather becomes extremely harsh sunlight.  Extremely harsh sunlight has all the properties of Sunny Day and also causes damaging Water moves to fail.  Extremely harsh sunlight ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified.  The weather cannot otherwise be changed except by the effects of Delta Stream and Primordial Sea.  Air Lock and Cloud Nine will prevent the effects of extremely harsh sunlight, including allowing Water moves to work, but will not allow the weather to be changed.', 'When this Pokémon enters battle or gains this ability, the weather becomes extremely harsh sunlight.  Extremely harsh sunlight has all the properties of Sunny Day and also causes damaging Water moves to fail.  Extremely harsh sunlight ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified.  The weather cannot otherwise be changed except by the effects of Delta Stream and Primordial Sea.  Air Lock and Cloud Nine will prevent the effects of extremely harsh sunlight, including allowing Water moves to work, but will not allow the weather to be changed.');
INSERT INTO abilities VALUES (191, 'delta-stream', 'generation-vi', 'When this Pokémon enters battle or gains this ability, the weather becomes a mysterious air current.  A mysterious air current causes moves to not be super effective against Flying; they do neutral damage instead.  Anticipation and Stealth Rock are not affected.  The mysterious air current ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified.  The weather cannot otherwise be changed except by the effects of Desolate Land and Primordial Sea.  Air Lock and Cloud Nine will prevent the effect of a mysterious air current, but will not allow the weather to be changed.', 'When this Pokémon enters battle or gains this ability, the weather becomes a mysterious air current.  A mysterious air current causes moves to not be super effective against Flying; they do neutral damage instead.  Anticipation and Stealth Rock are not affected.  The mysterious air current ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified.  The weather cannot otherwise be changed except by the effects of Desolate Land and Primordial Sea.  Air Lock and Cloud Nine will prevent the effect of a mysterious air current, but will not allow the weather to be changed.');
INSERT INTO abilities VALUES (192, 'stamina', 'generation-vii', 'Raises this Pokémon''s Defense by one stage when it takes damage from a move.', 'Raises this Pokémon''s Defense by one stage when it takes damage from a move.');
INSERT INTO abilities VALUES (193, 'wimp-out', 'generation-vii', 'After this Pokémon is hit by a move, if that move caused this Pokémon''s HP to drop below half, it switches out.', 'After this Pokémon is hit by a move, if that move caused this Pokémon''s HP to drop below half, it switches out.');
INSERT INTO abilities VALUES (194, 'emergency-exit', 'generation-vii', 'After this Pokémon is hit by a move, if that move caused this Pokémon''s HP to drop below half, it switches out.', 'After this Pokémon is hit by a move, if that move caused this Pokémon''s HP to drop below half, it switches out.');
INSERT INTO abilities VALUES (195, 'water-compaction', 'generation-vii', 'Raises this Pokémon''s Defense by two stages when it''s hit by a Water move.', 'Raises this Pokémon''s Defense by two stages when it''s hit by a Water move.');
INSERT INTO abilities VALUES (196, 'merciless', 'generation-vii', 'This Pokémon''s moves critical hit against poisoned targets.', 'This Pokémon''s moves critical hit against poisoned targets.');
INSERT INTO abilities VALUES (197, 'shields-down', 'generation-vii', 'When this Pokémon enters battle and at the end of each turn, if its HP is 50% or above, it changes into Meteor Form; otherwise, it changes into Core Form.  In Meteor Form, it cannot be given a major status ailment (though existing ones are not cured), cannot become drowsy from Yawn, and cannot use Rest (which will simply fail).  This ability cannot be copied, replaced, or nullified.  This ability only takes effect for Minior.', 'When this Pokémon enters battle and at the end of each turn, if its HP is 50% or above, it changes into Meteor Form; otherwise, it changes into Core Form.  In Meteor Form, it cannot be given a major status ailment (though existing ones are not cured), cannot become drowsy from Yawn, and cannot use Rest (which will simply fail).  This ability cannot be copied, replaced, or nullified.  This ability only takes effect for Minior.');
INSERT INTO abilities VALUES (198, 'stakeout', 'generation-vii', 'This Pokémon''s moves have double power against Pokémon that switched in this turn.', 'This Pokémon''s moves have double power against Pokémon that switched in this turn.');
INSERT INTO abilities VALUES (199, 'water-bubble', 'generation-vii', 'When this Pokémon is hit by a Fire move, the damage is halved.  When this Pokémon uses a Water move, the power is doubled. This Pokémon cannot be burned, and if it becomes burned, the burn is immediately cured.', 'When this Pokémon is hit by a Fire move, the damage is halved.  When this Pokémon uses a Water move, the power is doubled. This Pokémon cannot be burned, and if it becomes burned, the burn is immediately cured.');
INSERT INTO abilities VALUES (200, 'steelworker', 'generation-vii', 'This Pokémon''s Steel moves have 1.5× power.', 'This Pokémon''s Steel moves have 1.5× power.');
INSERT INTO abilities VALUES (201, 'berserk', 'generation-vii', 'Whenever this Pokémon takes damage from a move that causes its HP to drop below 50%, its Special Attack rises by one stage.', 'Whenever this Pokémon takes damage from a move that causes its HP to drop below 50%, its Special Attack rises by one stage.');
INSERT INTO abilities VALUES (202, 'slush-rush', 'generation-vii', 'During Hail, this Pokémon has double Speed.', 'During Hail, this Pokémon has double Speed.');
INSERT INTO abilities VALUES (203, 'long-reach', 'generation-vii', 'A move used by this Pokémon will not make contact.', 'A move used by this Pokémon will not make contact.');
INSERT INTO abilities VALUES (204, 'liquid-voice', 'generation-vii', 'When this Pokémon uses a move that is sound-based, that move''s type is Water.', 'When this Pokémon uses a move that is sound-based, that move''s type is Water.');
INSERT INTO abilities VALUES (205, 'triage', 'generation-vii', 'This Pokémon''s healing moves have their priority increased by 3.', 'This Pokémon''s healing moves have their priority increased by 3.');
INSERT INTO abilities VALUES (206, 'galvanize', 'generation-vii', 'When this Pokémon uses a Normal moves, that move is Electric its power is 1.2×.', 'When this Pokémon uses a Normal moves, that move is Electric its power is 1.2×.');
INSERT INTO abilities VALUES (207, 'surge-surfer', 'generation-vii', 'Doubles this Pokémon''s Speed on Electric Terrain.', 'Doubles this Pokémon''s Speed on Electric Terrain.');
INSERT INTO abilities VALUES (208, 'schooling', 'generation-vii', 'If this Pokémon is a Wishiwashi and level 20 or above, then when it enters battle and at the start of each turn, it becomes Schooling Form if its HP is 25% or higher and Solo Form otherwise.  This ability cannot be replaced, copied, or nullified.', 'If this Pokémon is a Wishiwashi and level 20 or above, then when it enters battle and at the start of each turn, it becomes Schooling Form if its HP is 25% or higher and Solo Form otherwise.  This ability cannot be replaced, copied, or nullified.');
INSERT INTO abilities VALUES (209, 'disguise', 'generation-vii', 'If this Pokémon is in its Disguised Form and takes damage from a move, it switches to its Busted Form and the damage is prevented.  Other effects are not prevented.  This ability cannot be copied or replaced.  This ability only takes effect for Mimikyu.', 'If this Pokémon is in its Disguised Form and takes damage from a move, it switches to its Busted Form and the damage is prevented.  Other effects are not prevented.  This ability cannot be copied or replaced.  This ability only takes effect for Mimikyu.');
INSERT INTO abilities VALUES (210, 'battle-bond', 'generation-vii', 'Transforms this Pokémon into Ash-Greninja after fainting an opponent.  Water Shuriken''s power is 20 and always hits three times.  This ability cannot be copied or replaced.  This ability only takes effect for Greninja.', 'Transforms this Pokémon into Ash-Greninja after fainting an opponent.  Water Shuriken''s power is 20 and always hits three times.  This ability cannot be copied or replaced.  This ability only takes effect for Greninja.');
INSERT INTO abilities VALUES (211, 'power-construct', 'generation-vii', 'Transforms 10% or 50% Zygarde into Complete Forme when its HP is below 50%.  This ability cannot be copied or replaced.  This ability only takes effect for Zygarde.', 'Transforms 10% or 50% Zygarde into Complete Forme when its HP is below 50%.  This ability cannot be copied or replaced.  This ability only takes effect for Zygarde.');
INSERT INTO abilities VALUES (212, 'corrosion', 'generation-vii', 'This Pokémon''s moves and item ignore the usual immunity of Poison and Steel Pokémon when attempting to inflict poison.', 'This Pokémon''s moves and item ignore the usual immunity of Poison and Steel Pokémon when attempting to inflict poison.');
INSERT INTO abilities VALUES (213, 'comatose', 'generation-vii', 'This Pokémon always acts as though it were Asleep.  It cannot be given another status ailment; it''s unaffected by Yawn; it can use Sleep Talk; and so on.', 'This Pokémon always acts as though it were Asleep.  It cannot be given another status ailment; it''s unaffected by Yawn; it can use Sleep Talk; and so on.');
INSERT INTO abilities VALUES (214, 'queenly-majesty', 'generation-vii', 'When an opposing Pokémon attempts to use a move that targets this Pokémon or an ally, and that move has priority, it will fail.', 'When an opposing Pokémon attempts to use a move that targets this Pokémon or an ally, and that move has priority, it will fail.');
INSERT INTO abilities VALUES (215, 'innards-out', 'generation-vii', 'When this Pokémon faints from an opponent''s move, that opponent takes damage equal to the HP this Pokémon had remaining.', 'When this Pokémon faints from an opponent''s move, that opponent takes damage equal to the HP this Pokémon had remaining.');
INSERT INTO abilities VALUES (216, 'dancer', 'generation-vii', 'Whenever another Pokémon uses a dance move, this Pokémon will use the same move immediately afterwards.', 'Whenever another Pokémon uses a dance move, this Pokémon will use the same move immediately afterwards.');
INSERT INTO abilities VALUES (217, 'battery', 'generation-vii', 'Ally Pokémon''s moves have their power increased to 1.3×.', 'Ally Pokémon''s moves have their power increased to 1.3×.');
