INSERT INTO abilities VALUES (219, 'dazzling', 'generation-vii', 'When an opposing Pokémon attempts to use a move that targets this Pokémon or an ally, and that move has priority, it will fail.', 'When an opposing Pokémon attempts to use a move that targets this Pokémon or an ally, and that move has priority, it will fail.');
INSERT INTO abilities VALUES (220, 'soul-heart', 'generation-vii', 'This Pokémon''s Special Attack rises by one stage every time any Pokémon faints.', 'This Pokémon''s Special Attack rises by one stage every time any Pokémon faints.');
