INSERT INTO abilities VALUES (225, 'rks-system', 'generation-vii', 'Changes this Pokémon''s type to match its held Memory.  This ability cannot be copied, replaced, or nullified.  This ability only takes effect for Silvally.', 'Changes this Pokémon''s type to match its held Memory.  This ability cannot be copied, replaced, or nullified.  This ability only takes effect for Silvally.');
INSERT INTO abilities VALUES (226, 'electric-surge', 'generation-vii', 'When this Pokémon enters battle, it changes the terrain to Electric Terrain.', 'When this Pokémon enters battle, it changes the terrain to Electric Terrain.');
INSERT INTO abilities VALUES (227, 'psychic-surge', 'generation-vii', 'When this Pokémon enters battle, it changes the terrain to Psychic Terrain.', 'When this Pokémon enters battle, it changes the terrain to Psychic Terrain.');
INSERT INTO abilities VALUES (228, 'misty-surge', 'generation-vii', 'When this Pokémon enters battle, it changes the terrain to Misty Terrain.', 'When this Pokémon enters battle, it changes the terrain to Misty Terrain.');
INSERT INTO abilities VALUES (229, 'grassy-surge', 'generation-vii', 'When this Pokémon enters battle, it changes the terrain to Grassy Terrain.', 'When this Pokémon enters battle, it changes the terrain to Grassy Terrain.');
INSERT INTO abilities VALUES (230, 'full-metal-body', 'generation-vii', 'This Pokémon''s stats cannot be lowered by other Pokémon''s moves or abilities.  This effect only applies to normal stat modifications and not more exotic effects such as Topsy-Turvy or Power Swap.  This Ability is not bypassed by Mold Breaker, Teravolt, or Turboblaze.', 'This Pokémon''s stats cannot be lowered by other Pokémon''s moves or abilities.  This effect only applies to normal stat modifications and not more exotic effects such as Topsy-Turvy or Power Swap.  This Ability is not bypassed by Mold Breaker, Teravolt, or Turboblaze.');
INSERT INTO abilities VALUES (231, 'shadow-shield', 'generation-vii', 'When this Pokémon has full HP, regular damage (not fixed damage!) from moves is halved.  This ability cannot be nullified.', 'When this Pokémon has full HP, regular damage (not fixed damage!) from moves is halved.  This ability cannot be nullified.');
INSERT INTO abilities VALUES (232, 'prism-armor', 'generation-vii', 'Super-effective damage this Pokémon takes is reduced to 0.75×.  This Ability is not bypassed by Mold Breaker, Teravolt, or Turboblaze.', 'Super-effective damage this Pokémon takes is reduced to 0.75×.  This Ability is not bypassed by Mold Breaker, Teravolt, or Turboblaze.');
INSERT INTO abilities VALUES (233, 'neuroforce', 'generation-vii', 'Increases super-effective damage dealt to 1.25×.', 'Increases super-effective damage dealt to 1.25×.');
INSERT INTO abilities VALUES (234, 'intrepid-sword', 'generation-viii', 'Boosts the Pokémon’s Attack stat the first time the Pokémon enters a battle.', 'Boosts the Pokémon’s Attack stat the first time the Pokémon enters a battle.');
INSERT INTO abilities VALUES (235, 'dauntless-shield', 'generation-viii', 'Boosts the Pokémon’s Defense stat the first time the Pokémon enters a battle.', 'Boosts the Pokémon’s Defense stat the first time the Pokémon enters a battle.');
INSERT INTO abilities VALUES (236, 'libero', 'generation-viii', 'Changes the Pokémon’s type to the type of the move it’s about to use. This works only once each time the Pokémon enters battle.', 'Changes the Pokémon’s type to the type of the move it’s about to use. This works only once each time the Pokémon enters battle.');
INSERT INTO abilities VALUES (237, 'ball-fetch', 'generation-viii', 'At any time after the first Poké Ball is thrown and fails to catch a Pokémon, at the end of a turn, if a Pokémon with Ball Fetch is on the field and not holding another item, it will pick up the same type of ball as the first one thrown.', 'At any time after the first Poké Ball is thrown and fails to catch a Pokémon, at the end of a turn, if a Pokémon with Ball Fetch is on the field and not holding another item, it will pick up the same type of ball as the first one thrown.');
INSERT INTO abilities VALUES (238, 'cotton-down', 'generation-viii', 'When the Pokémon is hit by an attack, it scatters cotton fluff around and lowers the Speed stats of all Pokémon except itself.', 'When the Pokémon is hit by an attack, it scatters cotton fluff around and lowers the Speed stats of all Pokémon except itself.');
INSERT INTO abilities VALUES (239, 'propeller-tail', 'generation-viii', 'Ignores the effects of opposing Pokémon’s Abilities and moves that draw in moves.', 'Ignores the effects of opposing Pokémon’s Abilities and moves that draw in moves.');
INSERT INTO abilities VALUES (240, 'mirror-armor', 'generation-viii', 'Bounces back only the stat-lowering effects that the Pokémon receives.', 'Bounces back only the stat-lowering effects that the Pokémon receives.');
INSERT INTO abilities VALUES (241, 'gulp-missile', 'generation-viii', 'When the Pokémon uses Surf or Dive, it will come back with prey. When it takes damage, it will spit out the prey to attack.', 'When the Pokémon uses Surf or Dive, it will come back with prey. When it takes damage, it will spit out the prey to attack.');
INSERT INTO abilities VALUES (242, 'stalwart', 'generation-viii', 'Ignores the effects of opposing Pokémon’s Abilities and moves that draw in moves.', 'Ignores the effects of opposing Pokémon’s Abilities and moves that draw in moves.');
INSERT INTO abilities VALUES (243, 'steam-engine', 'generation-viii', 'Raises the user''s Speed by three stages when it is hit by a Fire- or Water-type attack. The attack still deals damage.', 'Raises the user''s Speed by three stages when it is hit by a Fire- or Water-type attack. The attack still deals damage.');
INSERT INTO abilities VALUES (244, 'punk-rock', 'generation-viii', 'Boosts the power of sound-based moves. The Pokémon also takes half the damage from these kinds of moves.', 'Boosts the power of sound-based moves. The Pokémon also takes half the damage from these kinds of moves.');
INSERT INTO abilities VALUES (245, 'sand-spit', 'generation-viii', 'The Pokémon creates a sandstorm when it’s hit by an attack.', 'The Pokémon creates a sandstorm when it’s hit by an attack.');
INSERT INTO abilities VALUES (246, 'ice-scales', 'generation-viii', 'The Pokémon is protected by ice scales, which halve the damage taken from special moves.', 'The Pokémon is protected by ice scales, which halve the damage taken from special moves.');
INSERT INTO abilities VALUES (247, 'ripen', 'generation-viii', 'Ripens Berries and doubles their effect.', 'Ripens Berries and doubles their effect.');
INSERT INTO abilities VALUES (248, 'ice-face', 'generation-viii', 'When an Eiscue that''s in its Ice Face form is hit by a physical move, it takes no damage and changes into its Noice Face form. If a hailstorm or snowstorm begins while Eiscue is in its Noice Face form, or if it is sent out in its Noice Face form during hail, it will immediately revert to its Ice Face form.', 'When an Eiscue that''s in its Ice Face form is hit by a physical move, it takes no damage and changes into its Noice Face form. If a hailstorm or snowstorm begins while Eiscue is in its Noice Face form, or if it is sent out in its Noice Face form during hail, it will immediately revert to its Ice Face form.');
INSERT INTO abilities VALUES (249, 'power-spot', 'generation-viii', ' "The power of moves used by the allies of the Pokémon with Power Spot is increased by 30%."', ' "The power of moves used by the allies of the Pokémon with Power Spot is increased by 30%."');
INSERT INTO abilities VALUES (250, 'mimicry', 'generation-viii', 'Changes the Pokémon’s type depending on the terrain.', 'Changes the Pokémon’s type depending on the terrain.');
INSERT INTO abilities VALUES (251, 'screen-cleaner', 'generation-viii', 'When the Pokémon enters a battle, the effects of Light Screen, Reflect, and Aurora Veil are nullified for both opposing and ally Pokémon.', 'When the Pokémon enters a battle, the effects of Light Screen, Reflect, and Aurora Veil are nullified for both opposing and ally Pokémon.');
INSERT INTO abilities VALUES (252, 'steely-spirit', 'generation-viii', 'Powers up the Steel-type moves of the Pokémon and its allies.', 'Powers up the Steel-type moves of the Pokémon and its allies.');
INSERT INTO abilities VALUES (253, 'perish-body', 'generation-viii', 'When the Pokémon with Perish Body is hit with a contact move, both the attacker and the Pokémon with Perish Body will faint in three turns.', 'When the Pokémon with Perish Body is hit with a contact move, both the attacker and the Pokémon with Perish Body will faint in three turns.');
INSERT INTO abilities VALUES (254, 'wandering-spirit', 'generation-viii', 'The Pokémon exchanges Abilities with a Pokémon that hits it with a move that makes direct contact.', 'The Pokémon exchanges Abilities with a Pokémon that hits it with a move that makes direct contact.');
INSERT INTO abilities VALUES (255, 'gorilla-tactics', 'generation-viii', 'Boosts the Pokémon’s Attack stat but only allows the use of the first selected move.', 'Boosts the Pokémon’s Attack stat but only allows the use of the first selected move.');
INSERT INTO abilities VALUES (256, 'neutralizing-gas', 'generation-viii', 'While the Pokémon is in the battle, the effects of all other Pokémon’s Abilities will be nullified or will not be triggered.', 'While the Pokémon is in the battle, the effects of all other Pokémon’s Abilities will be nullified or will not be triggered.');
INSERT INTO abilities VALUES (257, 'pastel-veil', 'generation-viii', 'Prevents the Pokémon and its teammates from being poisoned. It also cures teammates of poisoning when it enters the battlefield.', 'Prevents the Pokémon and its teammates from being poisoned. It also cures teammates of poisoning when it enters the battlefield.');
INSERT INTO abilities VALUES (258, 'hunger-switch', 'generation-viii', 'The Pokémon changes its form, alternating between its Full Belly Mode and Hangry Mode after the end of every turn.', 'The Pokémon changes its form, alternating between its Full Belly Mode and Hangry Mode after the end of every turn.');
INSERT INTO abilities VALUES (259, 'quick-draw', 'generation-viii', 'If a Pokémon with this Ability selects a damaging move, it has a 30% chance of going first in its priority bracket.', 'If a Pokémon with this Ability selects a damaging move, it has a 30% chance of going first in its priority bracket.');
INSERT INTO abilities VALUES (260, 'unseen-fist', 'generation-viii', 'If the Pokémon uses moves that make direct contact, it can attack the target even if the target protects itself.', 'If the Pokémon uses moves that make direct contact, it can attack the target even if the target protects itself.');
INSERT INTO abilities VALUES (261, 'curious-medicine', 'generation-viii', 'When the Pokémon enters a battle, it scatters medicine from its shell, which removes all stat changes from allies.', 'When the Pokémon enters a battle, it scatters medicine from its shell, which removes all stat changes from allies.');
INSERT INTO abilities VALUES (262, 'transistor', 'generation-viii', 'Increases the power of Electric-type moves used by this Pokémon by 50%.', 'Increases the power of Electric-type moves used by this Pokémon by 50%.');
INSERT INTO abilities VALUES (263, 'dragons-maw', 'generation-viii', 'Increases the power of Dragon-type moves used by this Pokémon by 50%.', 'Increases the power of Dragon-type moves used by this Pokémon by 50%.');
INSERT INTO abilities VALUES (264, 'chilling-neigh', 'generation-viii', 'When the Pokémon knocks out a target, it utters a chilling neigh, which boosts its Attack stat.', 'When the Pokémon knocks out a target, it utters a chilling neigh, which boosts its Attack stat.');
INSERT INTO abilities VALUES (265, 'grim-neigh', 'generation-viii', 'When the Pokémon knocks out a target, it utters a terrifying neigh, which boosts its Sp. Atk stat.', 'When the Pokémon knocks out a target, it utters a terrifying neigh, which boosts its Sp. Atk stat.');
INSERT INTO abilities VALUES (266, 'as-one-glastrier', 'generation-viii', '', '');
INSERT INTO abilities VALUES (267, 'as-one-spectrier', 'generation-viii', '', '');
INSERT INTO abilities VALUES (268, 'lingering-aroma', 'generation-ix', 'Contact with the Pokémon changes the attacker’s Ability to Lingering Aroma.', 'Contact with the Pokémon changes the attacker’s Ability to Lingering Aroma.');
INSERT INTO abilities VALUES (269, 'seed-sower', 'generation-ix', 'Turns the ground into Grassy Terrain when the Pokémon is hit by an attack.', 'Turns the ground into Grassy Terrain when the Pokémon is hit by an attack.');
INSERT INTO abilities VALUES (270, 'thermal-exchange', 'generation-ix', 'Boosts the Attack stat when the Pokémon is hit by a Fire-type move. The Pokémon also cannot be burned.', 'Boosts the Attack stat when the Pokémon is hit by a Fire-type move. The Pokémon also cannot be burned.');
INSERT INTO abilities VALUES (271, 'anger-shell', 'generation-ix', 'When an attack causes its HP to drop to half or less, the Pokémon gets angry. This lowers its Defense and Sp. Def stats but boosts its Attack, Sp. Atk, and Speed stats.', 'When an attack causes its HP to drop to half or less, the Pokémon gets angry. This lowers its Defense and Sp. Def stats but boosts its Attack, Sp. Atk, and Speed stats.');
INSERT INTO abilities VALUES (272, 'purifying-salt', 'generation-ix', 'The Pokémon’s pure salt protects it from status conditions and halves the damage taken from Ghost-type moves.', 'The Pokémon’s pure salt protects it from status conditions and halves the damage taken from Ghost-type moves.');
INSERT INTO abilities VALUES (273, 'well-baked-body', 'generation-ix', 'The Pokémon takes no damage when hit by Fire-type moves. Instead, its Defense stat is sharply boosted.', 'The Pokémon takes no damage when hit by Fire-type moves. Instead, its Defense stat is sharply boosted.');
INSERT INTO abilities VALUES (274, 'wind-rider', 'generation-ix', 'Boosts the Pokémon’s Attack stat if Tailwind takes effect or if the Pokémon is hit by a wind move. The Pokémon also takes no damage from wind moves.', 'Boosts the Pokémon’s Attack stat if Tailwind takes effect or if the Pokémon is hit by a wind move. The Pokémon also takes no damage from wind moves.');
INSERT INTO abilities VALUES (275, 'guard-dog', 'generation-ix', 'Boosts the Pokémon’s Attack stat if intimidated. Moves and items that would force the Pokémon to switch out also fail to work.', 'Boosts the Pokémon’s Attack stat if intimidated. Moves and items that would force the Pokémon to switch out also fail to work.');
INSERT INTO abilities VALUES (276, 'rocky-payload', 'generation-ix', 'Increases the power of Rock-type moves used by this Pokémon by 50%.', 'Increases the power of Rock-type moves used by this Pokémon by 50%.');
INSERT INTO abilities VALUES (277, 'wind-power', 'generation-ix', 'The Pokémon becomes charged when it is hit by a wind move, boosting the power of the next Electric-type move the Pokémon uses.', 'The Pokémon becomes charged when it is hit by a wind move, boosting the power of the next Electric-type move the Pokémon uses.');
INSERT INTO abilities VALUES (278, 'zero-to-hero', 'generation-ix', 'The Pokémon transforms into its Hero Form when it switches out.', 'The Pokémon transforms into its Hero Form when it switches out.');
INSERT INTO abilities VALUES (279, 'commander', 'generation-ix', 'When the Pokémon enters a battle, it goes inside the mouth of an ally Dondozo if one is on the field. The Pokémon then issues commands from there.', 'When the Pokémon enters a battle, it goes inside the mouth of an ally Dondozo if one is on the field. The Pokémon then issues commands from there.');
INSERT INTO abilities VALUES (280, 'electromorphosis', 'generation-ix', 'The Pokémon becomes charged when it takes damage, boosting the power of the next Electric-type move the Pokémon uses.', 'The Pokémon becomes charged when it takes damage, boosting the power of the next Electric-type move the Pokémon uses.');
INSERT INTO abilities VALUES (281, 'protosynthesis', 'generation-ix', 'Boosts the Pokémon’s most proficient stat in harsh sunlight or if the Pokémon is holding Booster Energy.', 'Boosts the Pokémon’s most proficient stat in harsh sunlight or if the Pokémon is holding Booster Energy.');
INSERT INTO abilities VALUES (282, 'quark-drive', 'generation-ix', 'Boosts the Pokémon’s most proficient stat on Electric Terrain or if the Pokémon is holding Booster Energy.', 'Boosts the Pokémon’s most proficient stat on Electric Terrain or if the Pokémon is holding Booster Energy.');
INSERT INTO abilities VALUES (283, 'good-as-gold', 'generation-ix', 'A body of pure, solid gold gives the Pokémon full immunity to other Pokémon’s status moves.', 'A body of pure, solid gold gives the Pokémon full immunity to other Pokémon’s status moves.');
INSERT INTO abilities VALUES (284, 'vessel-of-ruin', 'generation-ix', 'The power of the Pokémon’s ruinous vessel lowers the Sp. Atk stats of all Pokémon except itself.', 'The power of the Pokémon’s ruinous vessel lowers the Sp. Atk stats of all Pokémon except itself.');
INSERT INTO abilities VALUES (285, 'sword-of-ruin', 'generation-ix', 'The power of the Pokémon’s ruinous sword lowers the Defense stats of all Pokémon except itself.', 'The power of the Pokémon’s ruinous sword lowers the Defense stats of all Pokémon except itself.');
INSERT INTO abilities VALUES (286, 'tablets-of-ruin', 'generation-ix', 'The power of the Pokémon’s ruinous wooden tablets lowers the Attack stats of all Pokémon except itself.', 'The power of the Pokémon’s ruinous wooden tablets lowers the Attack stats of all Pokémon except itself.');
INSERT INTO abilities VALUES (287, 'beads-of-ruin', 'generation-ix', 'The power of the Pokémon’s ruinous beads lowers the Sp. Def stats of all Pokémon except itself.', 'The power of the Pokémon’s ruinous beads lowers the Sp. Def stats of all Pokémon except itself.');
INSERT INTO abilities VALUES (288, 'orichalcum-pulse', 'generation-ix', 'Turns the sunlight harsh when the Pokémon enters a battle. The ancient pulse thrumming through the Pokémon also boosts its Attack stat in harsh sunlight.', 'Turns the sunlight harsh when the Pokémon enters a battle. The ancient pulse thrumming through the Pokémon also boosts its Attack stat in harsh sunlight.');
INSERT INTO abilities VALUES (289, 'hadron-engine', 'generation-ix', 'Turns the ground into Electric Terrain when the Pokémon enters a battle. The futuristic engine within the Pokémon also boosts its Sp. Atk stat on Electric Terrain.', 'Turns the ground into Electric Terrain when the Pokémon enters a battle. The futuristic engine within the Pokémon also boosts its Sp. Atk stat on Electric Terrain.');
INSERT INTO abilities VALUES (290, 'opportunist', 'generation-ix', 'If an opponent’s stat is boosted, the Pokémon seizes the opportunity to boost the same stat for itself.', 'If an opponent’s stat is boosted, the Pokémon seizes the opportunity to boost the same stat for itself.');
INSERT INTO abilities VALUES (291, 'cud-chew', 'generation-ix', 'When the Pokémon eats a Berry, it will regurgitate that Berry at the end of the next turn and eat it one more time.', 'When the Pokémon eats a Berry, it will regurgitate that Berry at the end of the next turn and eat it one more time.');
INSERT INTO abilities VALUES (292, 'sharpness', 'generation-ix', 'Increases the power of all ''slicing'' moves by 50%.', 'Increases the power of all ''slicing'' moves by 50%.');
INSERT INTO abilities VALUES (293, 'supreme-overlord', 'generation-ix', 'When the Pokémon enters a battle, its Attack and Sp. Atk stats are slightly boosted for each of the allies in its party that have already been defeated.', 'When the Pokémon enters a battle, its Attack and Sp. Atk stats are slightly boosted for each of the allies in its party that have already been defeated.');
INSERT INTO abilities VALUES (294, 'costar', 'generation-ix', 'When the Pokémon enters a battle, it copies an ally’s stat changes.', 'When the Pokémon enters a battle, it copies an ally’s stat changes.');
INSERT INTO abilities VALUES (295, 'toxic-debris', 'generation-ix', 'Scatters poison spikes at the feet of the opposing team when the Pokémon takes damage from physical moves.', 'Scatters poison spikes at the feet of the opposing team when the Pokémon takes damage from physical moves.');
INSERT INTO abilities VALUES (296, 'armor-tail', 'generation-ix', 'The mysterious tail covering the Pokémon’s head makes opponents unable to use priority moves against the Pokémon or its allies.', 'The mysterious tail covering the Pokémon’s head makes opponents unable to use priority moves against the Pokémon or its allies.');
INSERT INTO abilities VALUES (297, 'earth-eater', 'generation-ix', 'If hit by a Ground-type move, the Pokémon has its HP restored instead of taking damage.', 'If hit by a Ground-type move, the Pokémon has its HP restored instead of taking damage.');
INSERT INTO abilities VALUES (298, 'mycelium-might', 'generation-ix', 'The Pokémon will always act more slowly when using status moves, but these moves will be unimpeded by the Ability of the target.', 'The Pokémon will always act more slowly when using status moves, but these moves will be unimpeded by the Ability of the target.');
INSERT INTO abilities VALUES (299, 'minds-eye', 'generation-ix', 'Mind''s Eye enables the Pokémon with this Ability to hit Ghost-type Pokémon with damage-dealing Normal- and Fighting-type moves. It also prevents other Pokémon from lowering the Pokémon''s accuracy and ignores changes to the opponents'' evasion.', 'Mind''s Eye enables the Pokémon with this Ability to hit Ghost-type Pokémon with damage-dealing Normal- and Fighting-type moves. It also prevents other Pokémon from lowering the Pokémon''s accuracy and ignores changes to the opponents'' evasion.');
INSERT INTO abilities VALUES (300, 'supersweet-syrup', 'generation-ix', 'A sickly sweet scent spreads across the field the first time the Pokémon enters a battle, lowering the evasiveness of opposing Pokémon.', 'A sickly sweet scent spreads across the field the first time the Pokémon enters a battle, lowering the evasiveness of opposing Pokémon.');
INSERT INTO abilities VALUES (301, 'hospitality', 'generation-ix', 'When the Pokémon enters a battle, it showers its ally with hospitality, restoring a small amount of the ally''s HP.', 'When the Pokémon enters a battle, it showers its ally with hospitality, restoring a small amount of the ally''s HP.');
INSERT INTO abilities VALUES (302, 'toxic-chain', 'generation-ix', 'The power of the Pokémon''s toxic chain may badly poison any target the Pokémon hits with a move.', 'The power of the Pokémon''s toxic chain may badly poison any target the Pokémon hits with a move.');
INSERT INTO abilities VALUES (303, 'embody-aspect', 'generation-ix', 'Embody Aspect boosts a particular stat, depending on the form of a Terastallized Ogerpon', 'Embody Aspect boosts a particular stat, depending on the form of a Terastallized Ogerpon');
INSERT INTO abilities VALUES (304, 'tera-shift', 'generation-ix', 'When the Pokémon enters a battle, it absorbs the energy around itself and transforms into its Terastal Form.', 'When the Pokémon enters a battle, it absorbs the energy around itself and transforms into its Terastal Form.');
INSERT INTO abilities VALUES (305, 'tera-shell', 'generation-ix', 'The Pokémon’s shell contains the powers of each type. All damage-dealing moves that hit the Pokémon when its HP is full will not be very effective.', 'The Pokémon’s shell contains the powers of each type. All damage-dealing moves that hit the Pokémon when its HP is full will not be very effective.');
INSERT INTO abilities VALUES (306, 'teraform-zero', 'generation-ix', 'When Terapagos changes into its Stellar Form, it uses its hidden powers to eliminate all effects of weather and terrain, reducing them to zero.', 'When Terapagos changes into its Stellar Form, it uses its hidden powers to eliminate all effects of weather and terrain, reducing them to zero.');
INSERT INTO abilities VALUES (307, 'poison-puppeteer', 'generation-ix', 'When a Pokémon is poisoned by any of Pecharunt''s moves, it will also become confused.', 'When a Pokémon is poisoned by any of Pecharunt''s moves, it will also become confused.');
INSERT INTO abilities VALUES (308, 'piercing-drill', 'generation-ix', 'When the Pokémon uses contact moves, it can hit even targets that are protecting themselves, dealing 1/4 of the damage that the move would otherwise deal. Everything aside from the target''s protective effects is still triggered.', 'When the Pokémon uses contact moves, it can hit even targets that are protecting themselves, dealing 1/4 of the damage that the move would otherwise deal. Everything aside from the target''s protective effects is still triggered.');
INSERT INTO abilities VALUES (309, 'dragonize', 'generation-ix', 'The Pokémon''s Normal-type moves become Dragon-type moves and their power is boosted by 20%.', 'The Pokémon''s Normal-type moves become Dragon-type moves and their power is boosted by 20%.');
INSERT INTO abilities VALUES (310, 'mega-sol', 'generation-ix', 'Even when the sunlight has not turned harsh, the Pokémon can use its moves as if the weather were harsh sunlight.', 'Even when the sunlight has not turned harsh, the Pokémon can use its moves as if the weather were harsh sunlight.');
INSERT INTO abilities VALUES (311, 'spicy-spray', 'generation-ix', 'When the Pokémon takes damage from a move, it burns the attacker.', 'When the Pokémon takes damage from a move, it burns the attacker.');
